import React, { Fragment, useSyncExternalStore } from 'react';
import { getSessionSnapshot, subscribeSession } from '../../utils/storage';

export const useSession = () => useSyncExternalStore(subscribeSession, getSessionSnapshot);

// Reset the entire account-dependent view, including unsaved forms and pending
// component state, when this tab or another tab changes the signed-in account.
export default function SessionBoundary({ children }) {
  const session = useSession();
  return <Fragment key={session.revision}>{children}</Fragment>;
}
