const lessonsOf = course => course?.sourcesToExercises || course?.SourcesToExercises || [];

// Deterministic read-only normalization of older browser demo data. The server
// supplies its own persisted keys; these fallback keys are never sent to it.
export function normalizeCourseLessons(course) {
  const lessons = lessonsOf(course).map((lesson, index) => ({ ...lesson, lesson_key: lesson.lesson_key || `legacy-demo-${course.id}-${index}-${lesson.id ?? 0}` }));
  return { ...course, sourcesToExercises: lessons, progress_baseline: Array.isArray(course.progress_baseline) ? [...course.progress_baseline] : lessons.map(lesson => lesson.lesson_key) };
}

export function progressKeys(course, progress = {}) {
  if (progress.keyed) return Array.isArray(progress.viewed_keys) ? progress.viewed_keys : [];
  const normalized = normalizeCourseLessons(course);
  return (Array.isArray(progress.viewed) ? progress.viewed : [])
    .filter(index => Number.isInteger(index) && index >= 0 && index < normalized.progress_baseline.length)
    .map(index => normalized.progress_baseline[index]);
}

export function projectCourseProgress(course, progress = {}) {
  const normalized = normalizeCourseLessons(course);
  const keys = new Set(progressKeys(normalized, progress));
  const viewed = normalized.sourcesToExercises.flatMap((lesson, index) => keys.has(lesson.lesson_key) ? [index] : []);
  return { keyed: true, viewed_keys: [...keys], viewed, completed: viewed.length > 0 && viewed.length === normalized.sourcesToExercises.length };
}

export function progressKeyArgs(course, indices) {
  const lessons = lessonsOf(course);
  return lessons.every(lesson => !!lesson.lesson_key) ? [indices.map(index => lessons[index]?.lesson_key).filter(Boolean)] : [];
}

export function prepareDemoLessonSave(previous, course) {
  const old = previous ? normalizeCourseLessons(previous) : null;
  const used = new Set();
  const lessons = lessonsOf(course).map(lesson => {
    let before = old?.sourcesToExercises.find(item => item.lesson_key === lesson.lesson_key);
    if (!lesson.lesson_key) {
      const matches = old?.sourcesToExercises.filter(item => item.id === lesson.id && (item.source || '') === (lesson.source || '') && (item.description || '') === (lesson.description || '')) || [];
      if (matches.length === 1) before = matches[0];
    }
    let key = before?.lesson_key;
    if (!before || used.has(key) || (before.source || '') !== (lesson.source || '') || (before.description || '') !== (lesson.description || '')) {
      const bytes = new Uint8Array(16);
      window.crypto.getRandomValues(bytes);
      key = `lesson-${Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('')}`;
    }
    used.add(key);
    return { ...lesson, lesson_key: key };
  });
  return { ...course, sourcesToExercises: lessons, progress_baseline: old ? [...old.progress_baseline] : lessons.map(lesson => lesson.lesson_key) };
}
