import React, { useEffect, useMemo, useState } from 'react';
import { Activity, ArrowRight, BookOpenCheck, Download, Plus, Search, ShieldCheck, X, Users } from 'lucide-react';
import { Link } from 'react-router-dom';
import { fetchAdminCourses, fetchAllUsers, fetchUserbyToken, updateUserAdminStatus, updateUserCourseAccess } from '../../utils/api';
import './courseEditor.css';
import { projectCourseProgress } from '../../utils/courseProgress';

const getIsAdmin = user => !!(user?.is_admin || user?.isAdmin || user?.Is_Admin);

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [courses, setCourses] = useState([]);
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [query, setQuery] = useState('');
  const [message, setMessage] = useState('');
  const token = localStorage.getItem('alinavit:comparison:token');

  useEffect(() => {
    let mounted = true;
    const init = async () => {
      try {
        if (!token) return;
        const current = await fetchUserbyToken(token);
        const admin = getIsAdmin(current);
        if (!mounted) return;
        setCurrentUser(current);
        setIsAdmin(admin);
        if (admin) {
          const [usersList, courseList] = await Promise.all([fetchAllUsers(token), fetchAdminCourses(token)]);
          if (!mounted) return;
          setUsers(Array.isArray(usersList) ? usersList : []);
          setCourses(Array.isArray(courseList) ? courseList : []);
        }
      } catch (error) {
        if (mounted) {
          setIsAdmin(false);
          setMessage('Не удалось загрузить административные данные. Войдите снова или проверьте соединение.');
        }
      } finally {
        if (mounted) setLoading(false);
      }
    };
    init();
    return () => { mounted = false; };
  }, [token]);

  const participants = useMemo(() => users.map(user => {
    const owned = Array.isArray(user.purchased_courses) ? user.purchased_courses : [];
    const progress = user.progress_course || {};
    const lessonTotal = owned.reduce((total, id) => {
      const course = courses.find(item => Number(item.id) === Number(id));
      return total + (Number(course?.course_capacity) || (course?.sourcesToExercises || []).length || 0);
    }, 0);
    const viewed = owned.reduce((total, id) => {
      const course = courses.find(item => Number(item.id) === Number(id));
      return total + (course ? projectCourseProgress(course, progress[id]).viewed.length : 0);
    }, 0);
    return { ...user, ownedCount: owned.length, viewed, percent: lessonTotal ? Math.min(100, Math.round(viewed / lessonTotal * 100)) : 0 };
  }), [courses, users]);

  const filteredUsers = participants.filter(user => `${user.username || ''} ${user.email || ''}`.toLowerCase().includes(query.trim().toLowerCase()));
  const adminCount = participants.filter(getIsAdmin).length;
  const participantCount = participants.length - adminCount;
  const activeCount = participants.filter(user => user.ownedCount > 0).length;
  const viewedCount = participants.reduce((total, user) => total + user.viewed, 0);

  const toggleAdminStatus = async (username, currentStatus) => {
    if (username === currentUser?.username) {
      setMessage('Нельзя отозвать права у текущего аккаунта во время активной сессии.');
      return;
    }
    try {
      await updateUserAdminStatus(token, username, !currentStatus);
      setUsers(previous => previous.map(user => user.username === username ? { ...user, is_admin: !currentStatus } : user));
      setMessage(!currentStatus ? `${username}: выданы права администратора.` : `${username}: права администратора отозваны.`);
    } catch (error) {
      setMessage('Не удалось изменить права доступа.');
    }
  };

  const changeCourseAccess = async (username, courseId, granted) => {
    const course = courses.find(item => Number(item.id) === Number(courseId));
    if (!course) return;
    if (!granted && !window.confirm(`Убрать у ${username} доступ к «${course.title}»? Сохранённый прогресс этого материала будет удалён.`)) return;
    setMessage(granted ? 'Назначаем материал…' : 'Отзываем доступ…');
    try {
      await updateUserCourseAccess(token, username, Number(courseId), granted);
      setUsers(previous => previous.map(user => {
        if (user.username !== username) return user;
        const owned = new Set((user.purchased_courses || []).map(Number));
        if (granted) owned.add(Number(courseId));
        else owned.delete(Number(courseId));
        return { ...user, purchased_courses: Array.from(owned) };
      }));
      setMessage(`${username}: доступ ${granted ? 'назначен' : 'отозван'}.`);
    } catch (error) {
      setMessage('Не удалось изменить доступ к материалу.');
    }
  };

  const downloadParticipantsCsv = () => {
    const quote = value => `"${String(value ?? '').replace(/"/g, '""')}"`;
    const rows = [
      ['Участник', 'Email', 'Роль', 'Программ', 'Практик пройдено', 'Прогресс, %'],
      ...participants.map(user => [user.username, user.email, getIsAdmin(user) ? 'Администратор' : 'Участник', user.ownedCount, user.viewed, user.percent]),
    ];
    const csv = `\uFEFF${rows.map(row => row.map(quote).join(';')).join('\r\n')}`;
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `uchastniki-${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(url), 0);
    setMessage('Выгрузка участников подготовлена. Медицинских данных в ней нет.');
  };

  if (loading) return <div className="admin-state">Собираем сводку по платформе…</div>;
  if (!isAdmin) return <div className="admin-state">Доступ запрещён. Нужен аккаунт администратора.</div>;

  return (
    <section className="admin-page">
      <header className="admin-page__header">
        <div>
          <span className="eyebrow">Административный кабинет</span>
          <h1>Участники и доступы</h1>
          <p>Здесь видны только данные аккаунта и учебный прогресс. Сведения о здоровье в тестовой версии не собираются.</p>
        </div>
        <div className="admin-header-actions"><Link className="admin-header-link" to="/admin/applications">Заявки <ArrowRight size={16}/></Link><Link className="admin-header-link" to="/admin/courses-editor">Настроить программы <ArrowRight size={16}/></Link></div>
      </header>

      <div className="admin-metrics" aria-label="Сводка платформы">
        <div><Users/><span>Участников</span><strong>{participantCount}</strong></div>
        <div><ShieldCheck/><span>Администраторов</span><strong>{adminCount}</strong></div>
        <div><BookOpenCheck/><span>С активными программами</span><strong>{activeCount}</strong></div>
        <div><Activity/><span>Практик пройдено</span><strong>{viewedCount}</strong></div>
      </div>

      <div className="admin-tools">
        <label className="admin-search"><Search size={17}/><span className="sr-only">Поиск</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Найти по имени или email"/></label>
        <button type="button" className="admin-export" onClick={downloadParticipantsCsv}><Download size={17}/> Скачать CSV</button>
        <div className="admin-count"><Users size={19}/> {filteredUsers.length}</div>
      </div>

      {message && <div className="editor-message" role="status">{message}</div>}

      <div className="admin-table-wrap">
        <table className="admin-table">
          <thead><tr><th>Участник</th><th>Контакт</th><th>Материалы и прогресс</th><th>Роль</th><th>Действие</th></tr></thead>
          <tbody>{filteredUsers.map(user => {
            const userIsAdmin = getIsAdmin(user);
            const isCurrent = user.username === currentUser?.username;
            return (
              <tr key={user.username}>
                <td><strong>{user.username || 'Без имени'}</strong>{isCurrent && <small className="admin-you">Вы</small>}</td>
                <td>{user.email || '—'}</td>
                <td>
                  <div className="admin-progress-copy"><strong>{user.ownedCount}</strong> программ · <strong>{user.viewed}</strong> практик</div>
                  <div className="admin-progress-track" aria-label={`Прогресс ${user.percent}%`}><span style={{ width: `${user.percent}%` }}/></div>
                  <div className="admin-course-access" aria-label={`Материалы участника ${user.username}`}>
                    {(user.purchased_courses || []).map(id => {
                      const assigned = courses.find(course => Number(course.id) === Number(id));
                      return assigned ? <button type="button" key={id} title="Убрать доступ" onClick={() => changeCourseAccess(user.username, id, false)}><span>{assigned.content_type === 'checkpoint' ? 'Точка: ' : ''}{assigned.title}</span><X size={12}/></button> : null;
                    })}
                    <label><Plus size={13}/><span className="sr-only">Назначить материал</span><select aria-label={`Назначить материал пользователю ${user.username}`} value="" onChange={event => { if (event.target.value) changeCourseAccess(user.username, event.target.value, true); }}><option value="">Назначить…</option>{courses.filter(course => !(user.purchased_courses || []).map(Number).includes(Number(course.id))).map(course => <option key={course.id} value={course.id}>{course.content_type === 'checkpoint' ? 'Контрольная точка · ' : ''}{course.title}</option>)}</select></label>
                  </div>
                </td>
                <td><span className={`role-badge${userIsAdmin ? ' is-admin' : ''}`}>{userIsAdmin ? <><ShieldCheck size={14}/> Администратор</> : 'Участник'}</span></td>
                <td><button disabled={isCurrent} className={userIsAdmin ? 'admin-action is-danger' : 'admin-action'} onClick={() => toggleAdminStatus(user.username, userIsAdmin)}>{isCurrent ? 'Текущий аккаунт' : userIsAdmin ? 'Отозвать права' : 'Сделать администратором'}</button></td>
              </tr>
            );
          })}</tbody>
        </table>
        {filteredUsers.length === 0 && <div className="admin-empty">По вашему запросу никого не найдено.</div>}
      </div>
    </section>
  );
};

export default UserManagement;
