import React from 'react';
import { Activity, ArrowUpRight } from 'lucide-react';
import { resetPointerTilt, updatePointerTilt } from '../../utils/tilt';
import './course-card.css';

const pluralizeLessons = count => {
  if (count % 10 === 1 && count % 100 !== 11) return 'занятие';
  if (count % 10 >= 2 && count % 10 <= 4 && (count % 100 < 12 || count % 100 > 14)) return 'занятия';
  return 'занятий';
};

const stageNames = ['Осознание', 'Синхронизация', 'Устойчивые действия', 'Закрепление', 'Интеграция'];

const CourseCard = ({ course, actionButton, onActivate }) => {
  const count = Number(course.course_capacity) || (course.sourcesToExercises || []).length || 0;
  const marker = String(course.id || 'A').padStart(2, '0');
  const activateFromKeyboard = event => {
    if (!onActivate) return;
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      onActivate();
    }
  };

  return (
    <article
      className={`course-card${onActivate ? ' is-actionable' : ''}`}
      onPointerMove={event => updatePointerTilt(event, 5)}
      onPointerLeave={resetPointerTilt}
      onBlur={resetPointerTilt}
    >
      <div
        className="course-card__media"
        role={onActivate ? 'button' : undefined}
        tabIndex={onActivate ? 0 : undefined}
        aria-label={onActivate ? `Выбрать программу «${course.title}»` : undefined}
        aria-hidden={onActivate ? undefined : true}
        onClick={onActivate}
        onKeyDown={activateFromKeyboard}
      >
        <span className="course-card__category"><Activity size={14} /> {course.direction || 'Практический трек'}</span>
        <strong>{marker}</strong>
        <span className="course-card__axis" />
        <span className="course-card__orb" aria-hidden="true" />
        <small>ВНУТРЕННИЙ РИТМ · ПРАКТИКА</small>
      </div>
      <div className="course-card__body">
        <span className="course-card__level">{course.stage ? `Этап ${course.stage} · ${stageNames[course.stage - 1] || 'в своём ритме'}` : 'Онлайн · в своём ритме'}</span>
        {onActivate ? (
          <h2 className="course-title"><button type="button" onClick={onActivate}>{course.title}</button></h2>
        ) : <h2 className="course-title">{course.title}</h2>}
        <p className="course-description">{course.description || 'Последовательность небольших практик с понятным личным прогрессом.'}</p>
        <div className="course-card__footer">
          <span className="course-capacity">{count} {pluralizeLessons(count)}</span>
          {actionButton ? <div className="course-action">{actionButton}</div> : <ArrowUpRight size={22} />}
        </div>
      </div>
    </article>
  );
};

export default CourseCard;
