import React, { useEffect, useRef, useState } from 'react';
import { ClipboardList, Download, ShieldCheck } from 'lucide-react';
import { Link } from 'react-router-dom';
import { fetchMyDataExport, fetchUserbyToken } from '../../../utils/api';
import "./bodyProfile.css"
import { getSessionSnapshot } from '../../../utils/storage';

const BodyProfile = () => {
    const [user, setUser] = useState(null);
    const [token] = useState(localStorage.getItem('alinavit:comparison:token') || '');
    const [message, setMessage] = useState('');
    const [exporting, setExporting] = useState(false);
    const exportPending = useRef(false);
    const exportAfter = useRef(0);
    const alive = useRef(true);
    useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);

    useEffect(() => {
        if (token) {
            fetchUserbyToken(token)
                .then(data => setUser(data))
                .catch(err => setUser({ error: err.message }));
        }
    }, [token]);

    if (!token) return <div>Токен не найден. Войдите в систему.</div>;
    if (!user) return <div>Загрузка данных пользователя...</div>;
    if (user.error) return <div>Ошибка: {user.error}</div>;

    const isAdmin = !!(user && (user.is_admin || user.isAdmin || user.Is_Admin));

    const handleDataExport = async () => {
        if (exportPending.current) return;
        if (Date.now() < exportAfter.current) { setMessage('Копию можно запросить раз в минуту. Пожалуйста, подождите.'); return; }
        const revision = getSessionSnapshot().revision;
        exportPending.current = true;
        exportAfter.current = Date.now() + 60000;
        setExporting(true);
        setMessage('Готовим копию ваших данных…');
        try {
            const data = await fetchMyDataExport(token);
            if (!alive.current || getSessionSnapshot().revision !== revision) return;
            const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json;charset=utf-8' }));
            const link = document.createElement('a');
            link.href = url;
            link.download = `moi-dannye-${new Date().toISOString().slice(0, 10)}.json`;
            document.body.appendChild(link); link.click(); link.remove();
            window.setTimeout(() => URL.revokeObjectURL(url), 1000);
            setMessage('Копия данных подготовлена.');
        } catch (error) {
            if (alive.current) setMessage(error.status === 429 ? 'Слишком частые запросы. Повторите через минуту.' : 'Не удалось подготовить копию. Повторите через минуту.');
        } finally { exportPending.current = false; if (alive.current) setExporting(false); }
    };

    return (
        <div className="profile-card">
            <div className="profile-header">
                <div className="profile-avatar">{user.username?.[0]?.toUpperCase() || '?'}</div>
                <div>
                    <h1 className="profile-title">{user.username}</h1>
                    <div className="profile-sub">Пользователь платформы</div>
                </div>
            </div>
            <div className="profile-section">
                <div className="profile-actions">
                    <Link to="/courses/pass" className="glow-btn">Открыть мои занятия</Link>
                    <Link to="/courses/buy" className="glow-btn profile-action-secondary">Посмотреть программы</Link>
                </div>
                <div className="profile-label">Добавленные программы:</div>
                <div className="profile-courses">
                    {user.purchased_courses && user.purchased_courses.length > 0
                        ? user.purchased_courses.map(id => <Link className="profile-course-id" to={`/courses/pass/${id}`} key={id} aria-label={`Открыть программу ${id}`}>#{id}</Link>)
                        : <span className="profile-course-none">Нет</span>}
                </div>
            </div>
            <div className="profile-section">
                <div className="profile-label">Личная динамика:</div>
                <ul className="profile-progress-list">
                    {user.progress_course && Object.entries(user.progress_course).length > 0 ? (
                        Object.entries(user.progress_course).map(([courseId, progress]) => (
                            <li key={courseId}>
                                <Link className="profile-course-id" to={`/courses/pass/${courseId}`} aria-label={`Продолжить программу ${courseId}`}>#{courseId}</Link>: пройдено практик — {Array.isArray(progress.viewed) ? progress.viewed.length : 0}{progress.completed ? ' (завершено)' : ''}
                            </li>
                        ))
                    ) : (
                        <li className="profile-course-none">Нет данных</li>
                    )}
                </ul>
            </div>
            <details className="profile-section">
              <summary className="profile-label">Мои данные: зачем нужна копия?</summary>
              <div className="profile-data-section">
                <div><ShieldCheck size={20}/><div><p>Необязательная функция: сохранить у себя сведения об аккаунте, дневник, прогресс и заявку в техническом формате JSON. Это не скачивание видео или всей базы сайта. Файл содержит личные записи — не публикуйте его и не пересылайте посторонним.</p></div></div>
                <button type="button" className="glow-btn profile-action-secondary" disabled={exporting} onClick={handleDataExport}><Download size={16}/>{exporting ? 'Готовим копию…' : 'Скачать мою копию'}</button>
                {message && <small role="status">{message}</small>}
              </div>
            </details>
            {/* <div className="profile-section">
                <div className="profile-label">Уведомления:</div>
                <div className="profile-notify">{user.notifications && user.notifications.notify ? user.notifications.notify.body : 'Нет'}</div>
            </div> */}
            <div className="profile-actions">
                <Link to="/participation" className="glow-btn profile-action-secondary">
                    <ClipboardList size={16}/> Моя заявка на участие
                </Link>
                <Link to="/profile/edit" className="glow-btn">
                    Редактировать профиль
                </Link>
                {isAdmin && (
                    <>
                        <Link to="/admin/courses-editor" className="glow-btn">
                            Управление программами
                        </Link>
                        <Link to="/admin/users" className="glow-btn profile-action-secondary">
                             Управление доступами
                        </Link>
                        <Link to="/admin/applications" className="glow-btn profile-action-secondary">
                             Заявки на участие
                        </Link>
                        <Link to="/admin/research-forms" className="glow-btn profile-action-secondary">
                             Конструктор анкет
                        </Link>
                    </>
                )}
            </div>
        </div>
    );
};

export default BodyProfile;
