import React, { useEffect, useRef, useState } from 'react';
import { NotebookPen, Save } from 'lucide-react';
import { clearRhythmCheckIns, fetchRhythmCheckIns, saveRhythmCheckIn, STATIC_DEMO } from '../../utils/api';
import DiaryHistory from '../../components/Diary/DiaryHistory';
import '../Courses/pass/courses-pass.css';
import './diary.css';

const rhythmLabels = ['Очень тихий', 'Сбавленный', 'Ровный', 'Живой', 'Наполненный'];

export default function Diary() {
  const [checkIns, setCheckIns] = useState([]);
  const [rhythm, setRhythm] = useState(3);
  const [note, setNote] = useState('');
  const [checkInStatus, setCheckInStatus] = useState('');
  const [diaryBusy, setDiaryBusy] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [retry, setRetry] = useState(0);
  const diaryPending = useRef(false);
  const token = localStorage.getItem('alinavit:comparison:token') || '';

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError('');
    fetchRhythmCheckIns(token)
      .then(entries => { if (mounted) setCheckIns(Array.isArray(entries) ? entries : []); })
      .catch(err => { if (mounted) setError(err.message || 'Не удалось загрузить дневник.'); })
      .finally(() => { if (mounted) setLoading(false); });
    return () => { mounted = false; };
  }, [token, retry]);

  const handleCheckIn = async () => {
    if (diaryPending.current) return;
    diaryPending.current = true;
    setDiaryBusy(true);
    setCheckInStatus('Сохраняем отметку…');
    try {
      const saved = await saveRhythmCheckIn(token, { rhythm, note });
      setCheckIns(previous => [saved, ...previous]);
      setNote('');
      setCheckInStatus(STATIC_DEMO ? 'Отметка сохранена только в этом браузере.' : 'Отметка сохранена в вашем защищённом аккаунте.');
    } catch (saveError) {
      setCheckInStatus(saveError.message || 'Не удалось сохранить отметку.');
    } finally {
      diaryPending.current = false;
      setDiaryBusy(false);
    }
  };

  const handleClearCheckIns = async () => {
    if (diaryPending.current) return;
    if (!window.confirm('Удалить все личные отметки? Это действие нельзя отменить.')) return;
    diaryPending.current = true;
    setDiaryBusy(true);
    setCheckInStatus('Удаляем отметки…');
    try {
      await clearRhythmCheckIns(token);
      setCheckIns([]);
      setCheckInStatus('Все личные отметки удалены.');
    } catch (clearError) {
      setCheckInStatus(clearError.message || 'Не удалось удалить отметки.');
    } finally {
      diaryPending.current = false;
      setDiaryBusy(false);
    }
  };


  return (
    <section className="diary-page rhythm-dashboard">
      <div className="rhythm-dashboard__intro">
        <span className="eyebrow">Личное пространство</span>
        <h1>Дневник наблюдений</h1>
        <p>Замечайте, что поддерживает вас. Здесь нет правильных ответов, оценок и соревнования с другими.</p>
      </div>
      <p className="diary-storage-notice">{STATIC_DEMO
        ? 'Демоверсия: записи хранятся только в этом браузере и не переносятся на другие устройства. Не указывайте здесь медицинские или другие чувствительные сведения.'
        : 'Ваши отметки доступны только вам. Дневник не заменяет медицинскую консультацию и не является исследовательской анкетой.'}</p>
      {loading ? <p role="status">Открываем ваш дневник…</p> : error ? (
        <div className="common-page-card">
          <p role="alert">{error}</p>
          <button className="cta-primary" type="button" onClick={() => setRetry(value => value + 1)}>Попробовать снова</button>
        </div>
      ) : (
      <section className="rhythm-checkin" aria-labelledby="rhythm-checkin-title">
          <div className="rhythm-checkin__intro">
            <span className="eyebrow"><NotebookPen size={15}/> Личная отметка</span>
            <h2 id="rhythm-checkin-title">Как ощущается ваш ритм сегодня?</h2>
            <p>Это не медицинская анкета и не оценка результата. Короткая заметка помогает увидеть собственную последовательность.</p>
          </div>
          <div className="rhythm-checkin__form">
            <div className="rhythm-scale" role="group" aria-label="Ощущение ритма">
              {rhythmLabels.map((label, index) => (
                <button key={label} type="button" disabled={diaryBusy} className={rhythm === index + 1 ? 'is-active' : ''} aria-pressed={rhythm === index + 1} onClick={() => setRhythm(index + 1)}><strong>{index + 1}</strong><span>{label}</span></button>
              ))}
            </div>
            <label htmlFor="rhythm-note">Что сегодня помогло или помешало сохранить ритм?</label>
            <textarea id="rhythm-note" disabled={diaryBusy} value={note} maxLength={240} onChange={event => setNote(event.target.value)} placeholder="Например: прогулка, спокойный вечер, небольшой перерыв…" rows={4}/>
            <div className="rhythm-checkin__actions"><small>{note.length}/240</small><button type="button" disabled={diaryBusy} onClick={handleCheckIn}><Save size={16}/> Сохранить отметку</button></div>
            {checkInStatus && <p className="rhythm-checkin__status" role="status">{checkInStatus}</p>}
          </div>
          <DiaryHistory entries={checkIns} onClear={handleClearCheckIns} busy={diaryBusy}/>
      </section>

      )}
    </section>
  );
}

