import React, { useEffect, useState } from 'react';
import { BookOpen, Layers3, Save, Sparkles } from 'lucide-react';
import { deleteAdminCourse, fetchAdminCourses, fetchAdminCourseById, fetchUserbyToken, saveAdminCourse, STATIC_DEMO } from '../../utils/api';
import './courseEditor.css';
import { t } from '../../utils/i18n';
import { CHECKPOINT_TEMPLATES } from '../../utils/checkpointTemplates';
import { CHECKPOINT_MONTH_LABELS, hasCheckpointMonth } from '../../utils/checkpointSchedule';

const directions = ['Сон и восстановление', 'Дыхание', 'Движение', 'Питание', 'Осознанность', 'Эмоциональный баланс'];
const stages = ['Осознание', 'Синхронизация', 'Устойчивые действия', 'Закрепление', 'Интеграция'];
const emptyCourse = () => ({ title: '', description: '', direction: '', stage: 1, content_type: 'practice', checkpoint_week: 0, checkpoint_note: '', access_mode: 'private', sourcesToExercises: [], course_price: [] });

const CourseEditor = () => {
  const [loading, setLoading] = useState(true);
  const [courses, setCourses] = useState([]);
  const [selected, setSelected] = useState('new');
  const [course, setCourse] = useState(emptyCourse);
  const [message, setMessage] = useState('');
  const [creatingRoute, setCreatingRoute] = useState(false);
  const [newSuffix, setNewSuffix] = useState('');
  const token = localStorage.getItem('alinavit:comparison:token');
  const [isAdmin, setIsAdmin] = useState(false);
  const [, setLangState] = useState(localStorage.getItem('alinavit:comparison:lang') || 'ru');

  useEffect(() => {
    const init = async () => {
      try {
        if (token) {
          const u = await fetchUserbyToken(token);
          const admin = !!(u && (u.is_admin || u.isAdmin || u.Is_Admin));
          setIsAdmin(admin);
        }
      } catch (e) {
        setIsAdmin(false);
      }

      try {
        const list = token ? await fetchAdminCourses(token) : [];
        setCourses(list || []);
      } catch (e) {
        setCourses([]);
      }
      setLoading(false);
    };
    init();
  }, [token]);

  // re-render when language changes in header
  useEffect(() => {
    const onLang = () => setLangState(localStorage.getItem('alinavit:comparison:lang') || 'ru');
    window.addEventListener('langchange', onLang);
    return () => window.removeEventListener('langchange', onLang);
  }, []);

  useEffect(() => {
    if (selected === 'new') {
      setCourse(emptyCourse());
      return;
    }
    const id = selected;
    if (!id) return;
    (async () => {
      try {
        const data = await fetchAdminCourseById(token, id);
        setCourse(data || emptyCourse());
      } catch (e) {
          setCourse(emptyCourse());
        }
    })();
  }, [selected, token]);

  const updateLesson = (idx, field, value) => {
    setCourse(prev => {
      const next = { ...prev };
      next.sourcesToExercises = Array.isArray(next.sourcesToExercises) ? [...next.sourcesToExercises] : [];
      next.sourcesToExercises[idx] = { ...next.sourcesToExercises[idx], [field]: value };
      return next;
    });
  };

  const createMeasurementRoute = async () => {
    if (creatingRoute) return;
    setCreatingRoute(true);
    try {
      const current = await fetchAdminCourses(token);
      let created = 0;
      for (const template of CHECKPOINT_TEMPLATES) {
        if (current.some(item => item.content_type === 'checkpoint' && item.title === template.title)) continue;
        const saved = await saveAdminCourse(token, template);
        current.push(saved);
        created += 1;
        setCourses([...current]);
      }
      setMessage(created ? `Создано черновиков: ${created}. Сроки взяты из дополнения к паспорту; перед назначением заполните инструкции.` : 'Все пять точек уже существуют. Они не изменены; выберите нужную в списке для проверки срока.');
    } catch (error) {
      setMessage('Не удалось создать все точки. Сохранённые черновики доступны в списке; повторное нажатие добавит недостающие.');
    } finally {
      setCreatingRoute(false);
    }
  };

  const getLessonSuffixes = () => (
    Array.isArray(course.lessonSuffixes)
      ? course.lessonSuffixes.filter(Boolean)
      : []
  );

  const addLessonSuffix = () => {
    const suffix = sanitizeString(newSuffix);
    if (!suffix) return;
    setCourse(prev => {
      const existing = Array.isArray(prev.lessonSuffixes) ? prev.lessonSuffixes : [];
      if (existing.map(s => s.toLowerCase()).includes(suffix.toLowerCase())) {
        setMessage('Такой суффикс уже есть');
        setTimeout(()=>setMessage(''),3000);
        return prev;
      }
      return { ...prev, lessonSuffixes: [...existing, suffix] };
    });
    setNewSuffix('');
  };

  const removeLessonSuffix = (suffix) => {
    if (!window.confirm(`Удалить суффикс "${suffix}" из курса и уроков?`)) return;
    setCourse(prev => ({
      ...prev,
      lessonSuffixes: (prev.lessonSuffixes || []).filter(s => s !== suffix),
      sourcesToExercises: (prev.sourcesToExercises || []).map(l => ({
        ...l,
        suffixes: (l.suffixes || []).filter(s => s !== suffix),
      })),
    }));
  };

  const toggleLessonSuffix = (idx, suffix, checked) => {
    setCourse(prev => {
      const next = { ...prev };
      next.sourcesToExercises = Array.isArray(next.sourcesToExercises) ? [...next.sourcesToExercises] : [];
      const lesson = { ...(next.sourcesToExercises[idx] || {}) };
      const current = Array.isArray(lesson.suffixes) ? lesson.suffixes : [];
      lesson.suffixes = checked
        ? Array.from(new Set([...current, suffix]))
        : current.filter(s => s !== suffix);
      next.sourcesToExercises[idx] = lesson;
      return next;
    });
  };

  const addLesson = () => {
    setCourse(prev => {
      const existing = Array.isArray(prev.sourcesToExercises) ? prev.sourcesToExercises : [];
      const incomplete = existing.find(l => !l.title || (prev.content_type !== 'checkpoint' && !l.source));
      if (incomplete) {
        setMessage(t('incomplete_lesson_msg'));
        setTimeout(()=>setMessage(''),4000);
        return prev;
      }
      const next = { ...prev };
      next.sourcesToExercises = Array.isArray(next.sourcesToExercises) ? [...next.sourcesToExercises] : [];
      const newId = (next.sourcesToExercises.length ? (Math.max(...next.sourcesToExercises.map(l => Number(l.id||0))) + 1) : 0);
      next.sourcesToExercises.push({ title: '', id: newId, source: '', isWarmup: false, isFinal: false, suffixes: [], viewed: false });
      return next;
    });
  };

  const removeLesson = (idx) => {
    if (!window.confirm(t('confirm_delete_lesson'))) return;
    setCourse(prev => {
      const next = { ...prev };
      next.sourcesToExercises = [...(next.sourcesToExercises||[])];
      next.sourcesToExercises.splice(idx, 1);
      return next;
    });
  };

  const moveLesson = (index, offset) => {
    setCourse(previous => {
      const lessons = [...(previous.sourcesToExercises || [])];
      const target = index + offset;
      if (target < 0 || target >= lessons.length) return previous;
      [lessons[index], lessons[target]] = [lessons[target], lessons[index]];
      return { ...previous, sourcesToExercises: lessons };
    });
  };

  const addPriceItem = () => {
    setCourse(prev => {
      const next = { ...prev };
      next.course_price = Array.isArray(next.course_price) ? [...next.course_price] : [];
      const allowed = ['RUB','USD','EUR'];
      const existing = next.course_price.map(p => String(p.type||'').toUpperCase());
      const available = allowed.find(a => !existing.includes(a));
      if (!available) {
        setMessage(t('all_currencies_added'));
        setTimeout(()=>setMessage(''),3000);
        return prev;
      }
      next.course_price.push({ type: available, price: 0 });
      return next;
    });
  };

  const updatePrice = (idx, field, value) => {
    setCourse(prev => {
      const next = { ...prev };
      next.course_price = Array.isArray(next.course_price) ? [...next.course_price] : [];
      if (field === 'type') {
        const newType = String(value||'').toUpperCase();
        const other = next.course_price.map((p,i) => i===idx?null:String(p.type||'').toUpperCase());
        if (other.includes(newType)) {
          setMessage(t('currency_exists', { C: newType }));
          setTimeout(()=>setMessage(''),3000);
          return prev;
        }
        next.course_price[idx] = { ...next.course_price[idx], [field]: newType };
      } else {
        next.course_price[idx] = { ...next.course_price[idx], [field]: value };
      }
      return next;
    });
  };

  const removePrice = (idx) => {
    if (!window.confirm(t('confirm_delete_price'))) return;
    setCourse(prev => {
      const next = { ...prev };
      next.course_price = [...(next.course_price||[])];
      next.course_price.splice(idx, 1);
      return next;
    });
  };

  const deleteCourse = async () => {
    if (!window.confirm(t('confirm_delete_course'))) return;
    // if local draft, just remove locally
    if (String(selected).startsWith('local_')) {
      setCourses(prev => prev.filter(c => c.id !== selected));
      setSelected('new');
      setCourse(emptyCourse());
      setMessage(t('local_course_deleted'));
      setTimeout(()=>setMessage(''),3000);
      return;
    }
    try {
      await deleteAdminCourse(token, selected);
      // remove from list
      const sid = Number(selected);
      setCourses(prev => prev.filter(c => Number(c.id || c._id || c.course_id) !== sid));
      setSelected('new');
      setCourse(emptyCourse());
      setMessage('Программа удалена');
      setTimeout(()=>setMessage(''),3000);
    } catch (e) {
      setMessage(t('delete_error'));
      setTimeout(()=>setMessage(''),3000);
    }
  };

  const sanitizeString = (s) => {
    if (s == null) return '';
    return String(s).replace(/[<>]/g, '').trim();
  };

  const sanitizeCourse = (c) => {
    const out = { ...c };
    out.title = sanitizeString(out.title);
    out.description = sanitizeString(out.description);
    out.direction = sanitizeString(out.direction);
    out.stage = Math.min(5, Math.max(1, Number(out.stage) || 1));
    out.content_type = ['practice', 'checkpoint'].includes(out.content_type) ? out.content_type : 'practice';
    out.checkpoint_week = out.content_type === 'checkpoint' ? Math.min(24, Math.max(0, Number(out.checkpoint_week) || 0)) : 0;
    if (out.content_type === 'checkpoint' && hasCheckpointMonth(out)) out.checkpoint_week = 0;
    else delete out.checkpoint_month;
    out.checkpoint_note = out.content_type === 'checkpoint' ? sanitizeString(out.checkpoint_note).slice(0, 1200) : '';
    out.access_mode = ['free', 'paid', 'private'].includes(out.access_mode) ? out.access_mode : 'free';
    out.lessonSuffixes = Array.isArray(out.lessonSuffixes)
      ? Array.from(new Set(out.lessonSuffixes.map(sanitizeString).filter(Boolean)))
      : [];
    out.sourcesToExercises = Array.isArray(out.sourcesToExercises) ? out.sourcesToExercises.map(l => ({
      id: l.id,
      lesson_key: l.lesson_key,
      title: sanitizeString(l.title),
      source: sanitizeString(l.source),
      description: sanitizeString(l.description),
      isWarmup: !!l.isWarmup,
      isFinal: !!l.isFinal,
      suffixes: Array.isArray(l.suffixes)
        ? Array.from(new Set(l.suffixes.map(sanitizeString).filter(Boolean)))
        : [],
      viewed: !!l.viewed,
    })) : [];
    out.course_price = Array.isArray(out.course_price) ? out.course_price.map(p => ({ type: sanitizeString(p.type), price: Number(p.price) || 0 })) : [];
    return out;
  };

  const handleSave = async () => {
    const draftKey = selected === 'new' ? 'alinavit:comparison:courseEditor:new' : `alinavit:comparison:courseEditor:${selected}`;
    const safe = sanitizeCourse(course);
    if (!safe.title) {
      setMessage('Добавьте название программы.');
      return;
    }
    if (safe.content_type === 'checkpoint' && safe.sourcesToExercises.length === 0) {
      safe.sourcesToExercises = [{ id: 0, title: 'Ознакомиться с контрольной точкой', source: '', description: safe.checkpoint_note, isWarmup: false, isFinal: true, suffixes: [], viewed: false }];
    }
    if (safe.content_type !== 'checkpoint' && safe.access_mode !== 'private' && safe.sourcesToExercises.some(item => !item.title || !item.source)) {
      setMessage('У каждой доступной участникам практики должны быть название и ссылка.');
      return;
    }
    if (safe.access_mode === 'paid' && !safe.course_price.some(price => price.type === 'RUB' && price.price > 0)) {
      setMessage('Для платного доступа укажите положительную цену в рублях.');
      return;
    }
    const isLocal = selected === 'new' || String(selected).startsWith('local_');
    if (isLocal) {
      delete safe.id;
    }

    try {
      const saved = await saveAdminCourse(token, safe, isLocal ? undefined : selected);
      setCourse(saved);
      setSelected(String(saved.id));
      setCourses(prev => {
        const sid = Number(saved.id);
        const withoutDraft = prev.filter(c => String(c.id || c._id || c.course_id) !== String(selected));
        const idx = withoutDraft.findIndex(c => Number(c.id || c._id || c.course_id) === sid);
        if (idx >= 0) {
          const next = [...withoutDraft];
          next[idx] = saved;
          return next;
        }
        return [saved, ...withoutDraft];
      });
      setMessage('Программа сохранена');
    } catch (e) {
      localStorage.setItem(draftKey, JSON.stringify(safe));
      setMessage(`${t('local_saved_draft')} (${e.message || 'server unavailable'})`);
    }
    setTimeout(() => setMessage(''), 5000);
  };

  if (loading) return <div>Загрузка...</div>;
  if (!isAdmin) return <div>Доступ запрещён. Требуются права администратора.</div>;

  return (
    <div className="course-editor" style={{ padding: 20, maxWidth: 920, margin: '0 auto' }}>
      <header className="editor-header">
        <span className="eyebrow">Административный кабинет</span>
        <h1>Конструктор программ</h1>
        <p>Настройте программы, контрольные точки, этапы и доступ. {STATIC_DEMO ? 'В публичной демоверсии изменения сохраняются только в этом браузере.' : 'В рабочей версии изменения сохраняются на защищённом сервере.'}</p>
      </header>
      <div className="editor-panel">
        <strong>Пять измерений: T0, T1, T2, T3, T4</strong>
        <p>Создайте закрытые черновики входной, трёх промежуточных и итоговой точек. Затем заполните их и назначьте участникам.</p>
        <button type="button" className="glow-btn" disabled={creatingRoute} onClick={createMeasurementRoute}>{creatingRoute ? 'Создаём точки…' : 'Создать маршрут из пяти измерений'}</button>
      </div>
      <div className="editor-overview" aria-label="Сводка по контенту">
        <div><BookOpen size={19}/><span>Программ</span><strong>{courses.length}</strong></div>
        <div><Layers3 size={19}/><span>Практик в выбранной</span><strong>{(course.sourcesToExercises || []).length}</strong></div>
        <div><Sparkles size={19}/><span>Направлений методики</span><strong>6</strong></div>
      </div>
      <div className="editor-toolbar" style={{ marginBottom: 12, display: 'flex', alignItems: 'center', gap: 12 }}>
        <div>
          <label htmlFor="course-select">Выбранная программа</label>
          <select id="course-select" value={selected} onChange={e => setSelected(e.target.value)} style={{ marginLeft: 8 }}>
            <option value="new">— Новая программа —</option>
            {courses.map(c => (
              <option key={c.id || c._id || c.course_id} value={c.id || c._id || c.course_id}>{c.title || `#${c.id||c._id||c.course_id}`}</option>
            ))}
          </select>
        </div>
        <div>
          <button
            onClick={() => {
              // create a local draft course and select it
              const tempId = `local_${Date.now()}`;
              const newCourse = { ...emptyCourse(), id: tempId, title: 'Новая программа' };
              setCourses(prev => [newCourse, ...prev]);
              setSelected(tempId);
              setCourse(newCourse);
            }}
            className="glow-btn small-help"
          >Добавить программу</button>
        </div>
      </div>

      <div style={{ marginBottom: 12 }}>
        <label htmlFor="course-title">Название программы</label>
        <input id="course-title" value={course.title || ''} onChange={e => setCourse(prev => ({ ...prev, title: e.target.value }))} style={{ width: '100%', padding: 8, marginTop: 6 }} />
      </div>

      <div style={{ marginBottom: 12 }}>
        <label htmlFor="course-description">Короткое описание для участника</label>
        <textarea id="course-description" value={course.description || ''} onChange={e => setCourse(prev => ({ ...prev, description: e.target.value }))} style={{ width: '100%', padding: 8, marginTop: 6 }} rows={4} />
      </div>

      <div className="editor-meta-grid">
        <label>Тип материала
          <select value={course.content_type || 'practice'} onChange={e => setCourse(prev => ({ ...prev, content_type: e.target.value, access_mode: e.target.value === 'checkpoint' ? 'private' : prev.access_mode }))}>
            <option value="practice">Практическая программа</option>
            <option value="checkpoint">Контрольная точка</option>
          </select>
        </label>
        <label>Направление
          <select value={course.direction || ''} onChange={e => setCourse(prev => ({ ...prev, direction: e.target.value }))}>
            <option value="">Не выбрано</option>
            {directions.map(direction => <option key={direction} value={direction}>{direction}</option>)}
          </select>
        </label>
        <label>Этап программы
          <select value={Number(course.stage) || 1} onChange={e => setCourse(prev => ({ ...prev, stage: Number(e.target.value) }))}>
            {stages.map((stage, index) => <option key={stage} value={index + 1}>{index + 1}. {stage}</option>)}
          </select>
        </label>
        <label>Формат доступа
          <select disabled={course.content_type === 'checkpoint'} value={course.content_type === 'checkpoint' ? 'private' : course.access_mode || 'free'} onChange={e => setCourse(prev => ({ ...prev, access_mode: e.target.value }))}>
            <option value="free">Бесплатный демодоступ</option>
            <option value="paid">Платный доступ</option>
            <option value="private">Только по приглашению</option>
          </select>
        </label>
      </div>

      {course.content_type === 'checkpoint' && (
        <div className="editor-checkpoint-settings">
          <div>
            <span className="eyebrow">Маршрут участника</span>
            <h3>Настройка контрольной точки</h3>
            <p>В программе пять измерений — T0–T4. Точка доступна назначенным участникам. Сначала заполните инструкцию и срок, затем назначьте её в разделе участников.</p>
          </div>
          <label>Срок относительно начала программы
            <select value={hasCheckpointMonth(course) ? String(course.checkpoint_month) : ''} onChange={e => setCourse(prev => ({ ...prev, checkpoint_month: e.target.value === '' ? null : Number(e.target.value), checkpoint_week: 0 }))}>
              <option value="">Не задан в месяцах / прежняя неделя</option>
              {CHECKPOINT_MONTH_LABELS.map((label, month) => <option key={month} value={month}>{label}</option>)}
            </select>
          </label>
          <p>По дополнению к паспорту: T0 — до старта; T1, T2, T3, T4 — после 1, 2, 4 и 5 месяцев. Это относительные сроки, не календарные даты. Существующие материалы не меняются без сохранения.</p>
          {!hasCheckpointMonth(course) && <label>Прежний срок в неделях (0 — срок ещё не назначен)
            <input type="number" min="0" max="24" value={Number(course.checkpoint_week) || 0} onChange={e => setCourse(prev => ({ ...prev, checkpoint_week: Number(e.target.value) }))}/>
          </label>}
          <label>Организационная инструкция
            <textarea value={course.checkpoint_note || ''} maxLength={1200} rows={4} onChange={e => setCourse(prev => ({ ...prev, checkpoint_note: e.target.value }))} placeholder="Что участнику нужно сделать на этой точке. Не добавляйте медицинские вопросы до утверждения протокола и отдельного согласия."/>
          </label>
        </div>
      )}

      <div>
        <h3>{course.content_type === 'checkpoint' ? 'Шаги контрольной точки' : 'Практики программы'}</h3>
        <div className="editor-panel">
          <strong>Метки практик</strong>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 8, flexWrap: 'wrap' }}>
            <input
              value={newSuffix}
              onChange={e => setNewSuffix(e.target.value)}
              placeholder="Например: практика"
              aria-label="Новая метка практики"
              style={{ padding: 6, minWidth: 180 }}
            />
            <button onClick={addLessonSuffix} className="glow-btn small-help">Добавить метку</button>
          </div>
          {getLessonSuffixes().length > 0 && (
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 10 }}>
              {getLessonSuffixes().map(suffix => (
                <span key={suffix} className="editor-chip">
                  {suffix}
                  <button onClick={() => removeLessonSuffix(suffix)} className="editor-inline-delete" aria-label={`Удалить суффикс ${suffix}`}>×</button>
                </span>
              ))}
            </div>
          )}
        </div>
        {(course.sourcesToExercises || []).map((v, idx) => (
          <div key={v.lesson_key || `draft-${idx}`} className="editor-panel editor-lesson">
            <div className="editor-lesson__heading">
              <strong>
                Практика #{idx+1} {v.isWarmup? '(вводная)':''} {v.isFinal? '(итоговая)':''}
                {(v.suffixes || []).map(s => ` (${s})`).join('')}
              </strong>
              <div className="editor-lesson__order">
                <button type="button" disabled={idx === 0} onClick={() => moveLesson(idx, -1)} aria-label={`Переместить шаг ${idx + 1} выше`}>↑ Выше</button>
                <button type="button" disabled={idx === course.sourcesToExercises.length - 1} onClick={() => moveLesson(idx, 1)} aria-label={`Переместить шаг ${idx + 1} ниже`}>↓ Ниже</button>
                <button type="button" onClick={() => removeLesson(idx)} className="editor-inline-delete">Удалить</button>
              </div>
            </div>
            <div style={{ marginTop: 8 }}>
              <label htmlFor={`lesson-title-${idx}`}>Название</label>
              <input id={`lesson-title-${idx}`} value={v.title||''} onChange={e => updateLesson(idx, 'title', e.target.value)} style={{ width: '100%', padding: 6, marginTop: 4 }} />
            </div>
            <div style={{ marginTop: 8 }}>
              <label htmlFor={`lesson-source-${idx}`}>Ссылка на YouTube</label>
              <input id={`lesson-source-${idx}`} value={v.source||''} onChange={e => updateLesson(idx, 'source', e.target.value)} style={{ width: '100%', padding: 6, marginTop: 4 }} />
            </div>
            <div style={{ marginTop: 8, display: 'flex', gap: 12, alignItems: 'center' }}>
              <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}><input type="checkbox" checked={!!v.isWarmup} onChange={e=>updateLesson(idx,'isWarmup', e.target.checked)} /> Вводная</label>
              <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}><input type="checkbox" checked={!!v.isFinal} onChange={e=>updateLesson(idx,'isFinal', e.target.checked)} /> Итоговая</label>
              {getLessonSuffixes().map(suffix => (
                <label key={suffix} style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                  <input
                    type="checkbox"
                    checked={Array.isArray(v.suffixes) && v.suffixes.includes(suffix)}
                    onChange={e=>toggleLessonSuffix(idx, suffix, e.target.checked)}
                  />
                  {suffix}
                </label>
              ))}
              <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}><input type="checkbox" checked={!!v.viewed} onChange={e=>updateLesson(idx,'viewed', e.target.checked)} /> Просмотрено</label>
            </div>
            <div style={{ marginTop: 8 }}>
              <label htmlFor={`lesson-description-${idx}`}>Описание практики</label>
              <textarea id={`lesson-description-${idx}`} value={v.description||''} onChange={e => updateLesson(idx, 'description', e.target.value)} style={{ width: '100%', padding: 6, marginTop: 4 }} rows={3} />
            </div>
          </div>
        ))}
        <div style={{ marginTop: 8 }}>
          <button onClick={addLesson} className="glow-btn">{course.content_type === 'checkpoint' ? 'Добавить шаг' : 'Добавить практику'}</button>
        </div>
      </div>

      {course.access_mode === 'paid' && <div style={{ marginTop: 12 }}>
        <h3>Стоимость доступа</h3>
        {(course.course_price||[]).map((p, idx) => (
          <div key={idx} style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 8 }}>
            <select aria-label={`Валюта цены ${idx + 1}`} value={p.type||'RUB'} onChange={e=>updatePrice(idx,'type',e.target.value)}>
              <option>RUB</option>
              <option>USD</option>
              <option>EUR</option>
            </select>
            <input aria-label={`Сумма цены ${idx + 1}`} type="number" value={p.price||0} onChange={e=>updatePrice(idx,'price',Number(e.target.value))} style={{ width: 120, padding: 6 }} />
            <button onClick={()=>removePrice(idx)} className="editor-inline-delete">Удалить</button>
          </div>
        ))}
        <div>
          <button onClick={addPriceItem} className="glow-btn">Добавить цену</button>
        </div>
      </div>}

      <div className="editor-actions" style={{ marginTop: 18, display: 'flex', gap: 12, alignItems: 'center' }}>
        <button onClick={handleSave} className="glow-btn"><Save size={15}/> Сохранить программу</button>
        <button onClick={() => { navigator.clipboard?.writeText(JSON.stringify(course)); setMessage(t('copy_json')); setTimeout(()=>setMessage(''),3000); }} className="glow-btn">Скопировать JSON</button>
        {selected !== 'new' && <button onClick={deleteCourse} className="glow-btn editor-delete-course">Удалить программу</button>}
        {/* Кнопка завершения курса — доступна если все уроки отмечены просмотренными */}
        { Array.isArray(course.sourcesToExercises) && course.sourcesToExercises.length>0 && course.sourcesToExercises.every(l => l.viewed) && (
          <button onClick={() => { setMessage('Все практики отмечены. Программа готова к финальной проверке.'); setTimeout(()=>setMessage(''),3000); }} className="glow-btn">Готово к проверке</button>
        ) }
      </div>

      {message && <div className="editor-message" role="status">{message}</div>}
    </div>
  );
};

export default CourseEditor;
