import React, { useEffect, useMemo, useState } from 'react';
import { ArrowRight, CheckCircle2, Clock3, Inbox, MessageSquareText, Search } from 'lucide-react';
import { Link } from 'react-router-dom';
import { fetchParticipationApplications, fetchUserbyToken, updateParticipationStatus } from '../../utils/api';
import './courseEditor.css';

const statusLabels = {
  pending: 'Новая',
  contacted: 'Связались',
  accepted: 'Подтверждена',
  declined: 'Не подходит сейчас',
};

const availabilityLabels = {
  ready: 'Готов(а) к регулярному формату',
  need_details: 'Сначала нужны детали',
};

const getIsAdmin = user => !!(user?.is_admin || user?.isAdmin || user?.Is_Admin);

const ApplicationManagement = () => {
  const token = localStorage.getItem('alinavit:comparison:token') || '';
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [query, setQuery] = useState('');
  const [message, setMessage] = useState('');

  useEffect(() => {
    let mounted = true;
    const load = async () => {
      try {
        const user = await fetchUserbyToken(token);
        const admin = getIsAdmin(user);
        if (!mounted) return;
        setIsAdmin(admin);
        if (admin) {
          const data = await fetchParticipationApplications(token);
          if (mounted) setApplications(Array.isArray(data) ? data : []);
        }
      } catch (error) {
        if (mounted) setMessage('Не удалось загрузить заявки. Проверьте соединение или войдите снова.');
      } finally {
        if (mounted) setLoading(false);
      }
    };
    load();
    return () => { mounted = false; };
  }, [token]);

  const filtered = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return applications;
    return applications.filter(item => `${item.username || ''} ${item.email || ''} ${item.message || ''}`.toLowerCase().includes(normalized));
  }, [applications, query]);

  const metrics = {
    total: applications.length,
    pending: applications.filter(item => item.status === 'pending').length,
    contacted: applications.filter(item => item.status === 'contacted').length,
    accepted: applications.filter(item => item.status === 'accepted').length,
  };

  const changeStatus = async (username, status) => {
    setMessage('Сохраняем статус…');
    try {
      await updateParticipationStatus(token, username, status);
      setApplications(previous => previous.map(item => item.username === username ? { ...item, status, updated_at: new Date().toISOString() } : item));
      setMessage(`${username}: ${statusLabels[status].toLowerCase()}.`);
    } catch (error) {
      setMessage('Не удалось изменить статус заявки.');
    }
  };

  if (loading) return <div className="admin-state">Собираем заявки…</div>;
  if (!isAdmin) return <div className="admin-state">Доступ запрещён. Нужен аккаунт администратора.</div>;

  return (
    <section className="admin-page application-admin">
      <header className="admin-page__header">
        <div>
          <span className="eyebrow">Административный кабинет</span>
          <h1>Предварительные заявки</h1>
          <p>Организационные ответы перед набором. Эта форма не заменяет информированное согласие и не собирает медицинские сведения.</p>
        </div>
        <Link className="admin-header-link" to="/admin/users">Участники и доступы <ArrowRight size={16}/></Link>
      </header>

      <div className="admin-metrics" aria-label="Сводка заявок">
        <div><Inbox/><span>Всего заявок</span><strong>{metrics.total}</strong></div>
        <div><Clock3/><span>Новых</span><strong>{metrics.pending}</strong></div>
        <div><MessageSquareText/><span>Связались</span><strong>{metrics.contacted}</strong></div>
        <div><CheckCircle2/><span>Подтверждено</span><strong>{metrics.accepted}</strong></div>
      </div>

      <div className="admin-tools">
        <label className="admin-search"><Search size={17}/><span className="sr-only">Поиск</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Имя, email или сообщение"/></label>
        <div className="admin-count"><Inbox size={19}/> {filtered.length}</div>
      </div>

      {message && <div className="editor-message" role="status">{message}</div>}

      <div className="application-list">
        {filtered.map(item => (
          <article className="application-card" key={item.username}>
            <div className="application-card__top">
              <div><span className={`application-status is-${item.status || 'pending'}`}>{statusLabels[item.status] || statusLabels.pending}</span><h2>{item.username || 'Без имени'}</h2><a href={`mailto:${item.email}`}>{item.email || 'Email не указан'}</a></div>
              <label>Статус<select value={item.status || 'pending'} onChange={event => changeStatus(item.username, event.target.value)}><option value="pending">Новая</option><option value="contacted">Связались</option><option value="accepted">Подтверждена</option><option value="declined">Не подходит сейчас</option></select></label>
            </div>
            <dl className="application-meta"><div><dt>Готовность</dt><dd>{availabilityLabels[item.availability] || 'Не указано'}</dd></div><div><dt>Версия правил</dt><dd>{item.policy_version || '—'}</dd></div><div><dt>Обновлено</dt><dd>{item.updated_at ? new Date(typeof item.updated_at === 'number' ? item.updated_at * 1000 : item.updated_at).toLocaleDateString('ru-RU') : '—'}</dd></div></dl>
            {item.message ? <div className="application-note"><MessageSquareText size={17}/><p>{item.message}</p></div> : <p className="application-no-note">Дополнительных вопросов нет.</p>}
          </article>
        ))}
        {filtered.length === 0 && <div className="admin-empty">{applications.length ? 'По вашему запросу заявок не найдено.' : 'Новых заявок пока нет.'}</div>}
      </div>
    </section>
  );
};

export default ApplicationManagement;
