import { logoutUser } from './api';
import { clearUserData, getSessionSnapshot } from './storage';

export async function logoutCurrentSession() {
  const session = getSessionSnapshot();
  let warning = '';
  try { await logoutUser(session.token); } catch {
    warning = 'Вы вышли в этом браузере. Сервер не подтвердил завершение сессии: её ключ может оставаться действующим до истечения срока.';
  }
  // A late logout response must never clear a new account, even when the
  // original account was changed and then restored in another tab.
  if (getSessionSnapshot().revision !== session.revision) return null;
  clearUserData();
  return warning;
}
