const adminSeed = {
  username: 'admin',
  password: 'Admin123!',
  email: 'admin@alinavit.demo',
  purchased_courses: [],
  progress_course: {},
  is_admin: true,
};

const clone = value => JSON.parse(JSON.stringify(value));

function readState() {
  let state = { users: { admin: clone(adminSeed) }, courses: clone(DEMO_COURSES) };
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
    if (saved && saved.users) state = saved;
  } catch {
    // A damaged browser draft should not make the public demo unusable.
  }
  if (!state.users.admin) state.users.admin = clone(adminSeed);
  if (!Array.isArray(state.courses)) state.courses = clone(DEMO_COURSES);
  state.courses = state.courses.map(normalizeCourseLessons);
  return state;
}

function writeState(state) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function tokenFor(username) {
  return `demo:${encodeURIComponent(username)}`;
}

function usernameFromToken(token) {
  if (!token || !token.startsWith('demo:')) throw new Error('Сессия не найдена. Войдите снова.');
  return decodeURIComponent(token.slice(5));
}

function requireUser(state, token) {
  const username = usernameFromToken(token);
  const user = state.users[username];
  if (!user) throw new Error('Пользователь не найден');
  return { username, user };
}

function publicUser(user) {
  // Match the server's explicit safeUser contract. New private fields must not
  // silently appear in the general profile or administrator user list.
  return clone({
    username: user.username,
    email: user.email || '',
    purchased_courses: user.purchased_courses || [],
    progress_course: user.progress_course || {},
    is_admin: !!user.is_admin,
  });
}

export function demoLogin(username, password) {
  const state = readState();
  const matches = Object.entries(state.users).filter(([, account]) => account.username === username.trim() || (account.email && account.email === username.trim()));
  const entry = matches.length === 1 ? matches[0] : undefined;
  const [key, user] = entry || [];
  if (!user || user.password !== password) throw new Error('Неверное имя пользователя или пароль');
  return Promise.resolve({ token: tokenFor(key) });
}

export function demoRegister({ username, password, email = '' }) {
  const state = readState();
  const cleanName = String(username || '').trim();
  const cleanEmail = String(email || '').trim();
  if (!cleanName || !password) return Promise.reject(new Error('Введите имя пользователя и пароль'));
  if (Object.values(state.users).some(account => account.username === cleanName)) return Promise.reject(new Error('Такой пользователь уже существует'));
  if (cleanEmail && Object.values(state.users).some(account => account.email === cleanEmail)) return Promise.reject(new Error('Этот email уже используется'));
  // Storage keys are stable identities, even after a display/login name change.
  let key = cleanName;
  let suffix = 1;
  while (key in state.users) key = `${cleanName}#${suffix++}`;
  state.users[key] = {
    username: cleanName,
    password,
    email: cleanEmail,
    purchased_courses: [],
    progress_course: {},
    is_admin: false,
  };
  writeState(state);
  return Promise.resolve({ token: tokenFor(key) });
}

export function demoGetUser(token) {
  const state = readState();
  const result = publicUser(requireUser(state, token).user);
  Object.keys(result.progress_course).forEach(id => {
    const course = state.courses.find(item => Number(item.id) === Number(id));
    if (course) result.progress_course[id] = projectCourseProgress(course, result.progress_course[id]);
    else delete result.progress_course[id];
  });
  return Promise.resolve(result);
}

export function demoGetCourses() {
  return Promise.resolve(clone(readState().courses.filter(course => course.access_mode !== 'private' && course.content_type !== 'checkpoint')));
}

export function demoGetAdminCourses(token) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));
  return Promise.resolve(clone(state.courses));
}

export function demoGetUserCourses(token) {
  const state = readState();
  const { user } = requireUser(state, token);
  const owned = new Set(user.purchased_courses || []);
  return Promise.resolve(clone(state.courses.filter(course => owned.has(course.id))));
}

export function demoPurchase(token, courseId) {
  const state = readState();
  const { user } = requireUser(state, token);
  const id = Number(courseId);
  const course = state.courses.find(item => Number(item.id) === id);
  if (!course) return Promise.reject(new Error('Программа не найдена'));
  if (course.access_mode === 'private' || course.content_type === 'checkpoint') return Promise.reject(new Error('Программа доступна только по приглашению'));
  user.purchased_courses = Array.from(new Set([...(user.purchased_courses || []), id]));
  writeState(state);
  return Promise.resolve({ status: 'succeeded', demo: true, course_id: id });
}

export function demoUpdateProgress(token, courseId, viewed, completed, viewedKeys) {
  const state = readState();
  const { user } = requireUser(state, token);
  const id = Number(courseId);
  const course = state.courses.find(item => Number(item.id) === id);
  if (!course) return Promise.reject(new Error('Программа не найдена'));
  if (!(user.purchased_courses || []).some(owned => Number(owned) === id)) {
    return Promise.reject(new Error('Доступ запрещён'));
  }
  const count = (course.sourcesToExercises || []).length;
  const validViewed = Array.from(new Set((Array.isArray(viewed) ? viewed : [])
    .filter(index => Number.isInteger(index) && index >= 0 && index < count)));
  const currentKeys = course.sourcesToExercises.map(lesson => lesson.lesson_key);
  if (viewedKeys !== undefined && (!Array.isArray(viewedKeys) || viewedKeys.length > 200 || viewedKeys.some(key => !currentKeys.includes(key)))) {
    return Promise.reject(new Error('Программа изменилась. Обновите страницу перед сохранением.'));
  }
  if (viewedKeys === undefined && (currentKeys.length !== course.progress_baseline.length || currentKeys.some((key, index) => key !== course.progress_baseline[index]))) {
    return Promise.reject(new Error('Программа изменилась. Обновите страницу перед сохранением.'));
  }
  user.progress_course = user.progress_course || {};
  const keys = [...progressKeys(course, user.progress_course[id]), ...(viewedKeys || validViewed.map(index => currentKeys[index]))];
  user.progress_course[id] = projectCourseProgress(course, { keyed: true, viewed_keys: keys });
  writeState(state);
  return Promise.resolve({ ok: true });
}

