export function demoSaveRhythmCheckIn(token, payload) {
  const state = readState();
  const { user } = requireUser(state, token);
  const rhythm = Math.min(5, Math.max(1, Number(payload?.rhythm) || 3));
  const note = String(payload?.note || '').trim().slice(0, 240);
  const entry = {
    id: Date.now(),
    created_at: new Date().toISOString(),
    rhythm,
    note,
  };
  user.rhythm_check_ins = [entry, ...(Array.isArray(user.rhythm_check_ins) ? user.rhythm_check_ins : [])];
  writeState(state);
  return Promise.resolve(clone(entry));
}

export function demoClearRhythmCheckIns(token) {
  const state = readState();
  const { user } = requireUser(state, token);
  user.rhythm_check_ins = [];
  writeState(state);
  return Promise.resolve({ ok: true });
}

