export function demoSaveParticipationApplication(token, payload) {
  const state = readState();
  const { user } = requireUser(state, token);
  const now = new Date().toISOString();
  const existing = user.participation_application;
  const application = {
    status: existing?.status || 'pending',
    availability: payload.availability,
    message: String(payload.message || '').trim().slice(0, 600),
    adult_confirmed: !!payload.adult_confirmed,
    privacy_acknowledged: !!payload.privacy_acknowledged,
    policy_version: 'privacy-draft-2026-09-05',
    created_at: existing?.created_at || now,
    updated_at: now,
  };
  if (!application.adult_confirmed || !application.privacy_acknowledged) return Promise.reject(new Error('Нужно подтвердить возраст и правила обработки данных'));
  if (!['ready', 'need_details'].includes(application.availability)) return Promise.reject(new Error('Выберите вариант участия'));
  user.participation_application = application;
  writeState(state);
  return Promise.resolve(clone(application));
}

export function demoGetParticipationApplications(token) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));
  return Promise.resolve(Object.values(state.users)
    .filter(account => account.participation_application)
    .map(account => ({ username: account.username, email: account.email || '', ...clone(account.participation_application) }))
    .sort((a, b) => String(b.updated_at).localeCompare(String(a.updated_at))));
}

export function demoUpdateParticipationStatus(token, username, status) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));
  if (!['pending', 'contacted', 'accepted', 'declined'].includes(status)) return Promise.reject(new Error('Недопустимый статус заявки'));
  const target = Object.values(state.users).find(account => account.username === username);
  if (!target?.participation_application) return Promise.reject(new Error('Заявка не найдена'));
  target.participation_application.status = status;
  target.participation_application.updated_at = new Date().toISOString();
  writeState(state);
  return Promise.resolve({ ok: true });
}

export function demoUpdateProfile(token, userData) {
  const state = readState();
  const { user } = requireUser(state, token);
  const username = String(userData.username || '').trim();
  const email = String(userData.email || '').trim();
  if (!username) return Promise.reject(new Error('Введите имя пользователя'));
  const others = Object.values(state.users).filter(account => account !== user);
  if (others.some(account => account.username === username)) return Promise.reject(new Error('Такое имя пользователя уже используется'));
  if (email && others.some(account => account.email === email)) return Promise.reject(new Error('Этот email уже используется'));
  user.username = username;
  user.email = email;
  writeState(state);
  return Promise.resolve(publicUser(user));
}

