export function demoUpdateAdminStatus(token, username, isAdmin) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));
  const target = Object.values(state.users).find(account => account.username === username);
  if (!target) return Promise.reject(new Error('Пользователь не найден'));
  target.is_admin = !!isAdmin;
  writeState(state);
  return Promise.resolve({ ok: true });
}

export function demoUpdateUserCourseAccess(token, username, courseId, granted) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));
  const target = Object.values(state.users).find(account => account.username === username);
  const id = Number(courseId);
  if (!target) return Promise.reject(new Error('Пользователь не найден'));
  if (!state.courses.some(course => Number(course.id) === id)) return Promise.reject(new Error('Программа не найдена'));
  const owned = new Set((target.purchased_courses || []).map(Number));
  if (granted) owned.add(id);
  else {
    owned.delete(id);
    if (target.progress_course) delete target.progress_course[id];
  }
  target.purchased_courses = Array.from(owned);
  writeState(state);
  return Promise.resolve({ ok: true });
}

export function demoGetAdminCourse(token, courseId) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));
  const course = state.courses.find(item => Number(item.id) === Number(courseId));
  if (!course) return Promise.reject(new Error('Программа не найдена'));
  return Promise.resolve(clone(course));
}

export function demoSaveAdminCourse(token, course, courseId) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));

  const saved = clone(course || {});
  if (saved.checkpoint_month != null && (!Number.isInteger(saved.checkpoint_month) || saved.checkpoint_month < 0 || saved.checkpoint_month > 5)) {
    return Promise.reject(new Error('Месяц контрольной точки должен быть от 0 до 5'));
  }
  if (saved.content_type === 'checkpoint') {
    saved.access_mode = 'private';
    saved.course_price = [];
    if (saved.checkpoint_month != null) saved.checkpoint_week = 0;
  } else delete saved.checkpoint_month;
  const requestedId = Number(courseId || saved.id);
  saved.id = requestedId || (state.courses.reduce((max, item) => Math.max(max, Number(item.id) || 0), 0) + 1);
  saved.sourcesToExercises = Array.isArray(saved.sourcesToExercises) ? saved.sourcesToExercises : [];
  saved.course_price = Array.isArray(saved.course_price) ? saved.course_price : [];
  saved.course_capacity = saved.sourcesToExercises.length;

  const index = state.courses.findIndex(item => Number(item.id) === saved.id);
  const prepared = prepareDemoLessonSave(index >= 0 ? state.courses[index] : null, saved);
  if (index >= 0) state.courses[index] = prepared;
  else state.courses.unshift(prepared);
  writeState(state);
  return Promise.resolve(clone(prepared));
}

export function demoDeleteAdminCourse(token, courseId) {
  const state = readState();
  const { user } = requireUser(state, token);
  if (!user.is_admin) return Promise.reject(new Error('Доступ запрещён'));
  const id = Number(courseId);
  state.courses = state.courses.filter(item => Number(item.id) !== id);
  Object.values(state.users).forEach(account => {
    account.purchased_courses = (account.purchased_courses || []).filter(item => Number(item) !== id);
    if (account.progress_course) delete account.progress_course[id];
  });
  writeState(state);
  return Promise.resolve({ ok: true });
}
