import React, { useEffect } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { Activity, Home, Library, NotebookPen, UserRound } from 'lucide-react';
import Header from '../header/Header';
import Footer from '../footer/Footer';
import SessionNotice from '../Auth/SessionNotice';
import './layout.css';
import '../../global-theme.css';
import { t } from '../../utils/i18n';

export const Layout = ({ children }) => {
  const location = useLocation();
  const auth = !!localStorage.getItem('alinavit:comparison:token');

  useEffect(() => {
    document.body.setAttribute('data-theme', 'light');
  }, []);

  useEffect(() => {
    const path = location.pathname.replace(/\/+$/, '') || '/';
    let section = '';
    if (path === '/' || path === '/about') section = t('header_about');
    else if (path.startsWith('/courses/pass/')) section = 'Практика';
    else if (path === '/courses/buy') section = 'Практики';
    else if (path === '/courses/pass') section = 'Мой ритм';
    else if (path === '/diary') section = 'Дневник';
    else if (path === '/profile') section = t('header_my_profile');
    else if (path === '/support' || path === '/participation') section = t('support_title');
    else if (path === '/admin/courses-editor') section = t('course_editor_title');
    else if (path === '/admin/applications') section = 'Заявки';
    else if (path === '/admin/users') section = 'Пользователи';
    else if (path === '/admin/research-forms') section = 'Конструктор анкет';
    else if (path === '/auth') section = t('login_title');
    else if (path === '/reg') section = 'Регистрация';
    else if (path === '/profile/edit') section = 'Редактирование профиля';
    else if (path === '/notifications') section = 'Уведомления';
    else if (path === '/terms') section = 'Условия использования';
    else if (path === '/privacy') section = 'Конфиденциальность';
    else if (path === '/yookassa-ip') section = 'Реквизиты';
    document.title = section ? `Внутренний ритм — ${section}` : 'Внутренний ритм';
  }, [location.pathname]);

  useEffect(() => {
    if (location.hash) {
      const target = document.getElementById(location.hash.slice(1));
      if (target) window.requestAnimationFrame(() => target.scrollIntoView({ behavior: 'smooth', block: 'start' }));
      return;
    }
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, [location.pathname, location.hash]);

  return (
    <div className="site-shell">
      <Header />
      <main className="main-content"><SessionNotice/>{children}</main>
      <Footer />
      <nav className="mobile-tabbar" aria-label="Мобильная навигация">
        <NavLink to="/about"><Home size={19}/><span>Главная</span></NavLink>
        <NavLink to="/courses/buy"><Activity size={19}/><span>Практики</span></NavLink>
        {auth && <NavLink to="/courses/pass"><Library size={19}/><span>Мой ритм</span></NavLink>}
        {auth && <NavLink to="/diary"><NotebookPen size={19}/><span>Дневник</span></NavLink>}
        <NavLink to={auth ? '/profile' : '/auth'}><UserRound size={19}/><span>{auth ? 'Профиль' : 'Войти'}</span></NavLink>
      </nav>
    </div>
  );
};
