import React from 'react';
import { Bell } from 'lucide-react';
import './notifications.css';

const Notifications = () => (
  <section className="notifications-page" aria-labelledby="notifications-title">
    <span className="eyebrow">Личный кабинет</span>
    <h1 id="notifications-title">Уведомления</h1>
    <div className="notifications-empty">
      <Bell size={28} aria-hidden="true" />
      <h2>Здесь пока тихо</h2>
      <p>В этом разделе появятся важные сообщения о программах и вашем доступе.</p>
    </div>
  </section>
);

export default Notifications;
