import React from 'react';
import { ArrowUpRight, CalendarRange, MessageCircle, NotebookPen, ShieldCheck } from 'lucide-react';
import { Link } from 'react-router-dom';
import { resetPointerTilt, updatePointerTilt } from '../../utils/tilt';
import './support.css';

const participationTopics = [
  { title: 'Пять месяцев', text: 'Программа предполагает последовательный путь от наблюдения за текущим состоянием до своей системы поддерживающих привычек.', icon: CalendarRange },
  { title: 'Регулярное участие', text: 'Практики, короткий дневник и еженедельная обратная связь помогают замечать личную динамику.', icon: NotebookPen },
  { title: 'Добровольность', text: 'Участник знакомится с условиями заранее, сохраняет право прекратить участие и не сравнивается с другими.', icon: ShieldCheck },
];

const Support = () => (
  <div className="support-page">
    <section className="support-hero">
      <span className="eyebrow">Участие в проекте</span>
      <h1>Сначала понять формат</h1>
      <p>«Внутренний ритм» — не марафон и не набор тренировок. Это пятимесячная программа наблюдения, практик и обратной связи.</p>
    </section>

    <section className="support-grid" aria-label="Основные условия участия">
      {participationTopics.map(topic => {
        const Icon = topic.icon;
        return (
          <article
            key={topic.title}
            className="support-card"
            onPointerMove={event => updatePointerTilt(event, 4)}
            onPointerLeave={resetPointerTilt}
          >
            <Icon size={22} />
            <h2>{topic.title}</h2>
            <p>{topic.text}</p>
          </article>
        );
      })}
    </section>

    <section className="support-contact">
      <MessageCircle size={24} />
      <div>
        <span className="eyebrow">Сообщество проекта</span>
        <h2>Уточнить детали у Алины</h2>
        <p>Точные даты набора, нагрузка, условия участия и формат обратной связи сейчас уточняются. Новости публикуются в сообществе VK.</p>
        <div className="support-actions">
          <Link className="support-apply" to="/participation">Подать предварительную заявку <ArrowUpRight size={16}/></Link>
          <a className="support-vk" href="https://vk.ru/club236212766" target="_blank" rel="noreferrer">Открыть сообщество VK <ArrowUpRight size={16}/></a>
        </div>
      </div>
    </section>

    <p className="support-note">В заявке нужны только организационные ответы. Не оставляйте диагнозы и другие сведения о здоровье.</p>
  </div>
);

export default Support;
