export const CHECKPOINT_MONTH_LABELS = [
  'До начала программы',
  'По окончании 1-го месяца',
  'По окончании 2-го месяца',
  'По окончании 3-го месяца',
  'По окончании 4-го месяца',
  'По окончании 5-го месяца',
];

export const hasCheckpointMonth = course => Number.isInteger(course?.checkpoint_month)
  && course.checkpoint_month >= 0 && course.checkpoint_month <= 5;

export function checkpointScheduleLabel(course) {
  if (hasCheckpointMonth(course)) return CHECKPOINT_MONTH_LABELS[course.checkpoint_month];
  const week = Number(course?.checkpoint_week);
  return Number.isInteger(week) && week > 0 && week <= 24 ? `Неделя ${week}` : 'Срок уточняется';
}

// Group calendar-month schedules before legacy weeks and unspecified schedules.
// Do not convert months into a guessed number of weeks or calendar dates.
export function compareCheckpointSchedules(a, b) {
  const key = course => hasCheckpointMonth(course) ? course.checkpoint_month
    : Number(course?.checkpoint_week) > 0 ? 100 + Number(course.checkpoint_week) : 200;
  return key(a) - key(b);
}
