import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { confirmEmailLogin } from '../../utils/api';
import { getSessionSnapshot, saveToken } from '../../utils/storage';
import { useSession } from './SessionBoundary';

export default function EmailConfirmation({ challenge, onResend, onBack }) {
  const [code, setCode] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [remaining, setRemaining] = useState(challenge.retry_after || 60);
  const alive = useRef(true);
  const pending = useRef(false);
  const session = useSession();
  const navigate = useNavigate();
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  useEffect(() => {
    const deadline = Date.now() + (challenge.retry_after || 60) * 1000;
    setCode(''); setRemaining(challenge.retry_after || 60);
    const timer = setInterval(() => setRemaining(Math.max(0, Math.ceil((deadline - Date.now()) / 1000))), 1000);
    return () => clearInterval(timer);
  }, [challenge]);
  const run = async (resend = false) => {
    if (pending.current || (resend && remaining > 0)) return;
    pending.current = true; setBusy(true); setError('');
    try {
      if (resend) { await onResend(); return; }
      const data = await confirmEmailLogin(challenge.challenge_id, code);
      if (!alive.current || getSessionSnapshot().revision !== session.revision) return;
      saveToken(data.token); navigate('/profile');
    } catch (err) { if (alive.current) setError(err.message); }
    finally { pending.current = false; if (alive.current) setBusy(false); }
  };
  return <div className="auth-container"><form onSubmit={event => { event.preventDefault(); run(); }}>
    <h1>Проверьте почту</h1>
    <p className="auth-help">Введите 8 цифр из письма «Внутренний ритм». Код действует 10 минут. Проверьте также папку «Спам».</p>
    <div className="input-container"><label htmlFor="email-code">Код из письма</label>
      <input id="email-code" value={code} onChange={event => setCode(event.target.value.replace(/\D/g, '').slice(0, 8))} inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{8}" maxLength={8} required autoFocus disabled={busy}/>
    </div>
    {error && <p className="auth-error" role="alert">{error}</p>}
    <div className="button-container">
      <button disabled={busy || code.length !== 8}>{busy ? 'Проверяем…' : 'Подтвердить вход'}</button>
      <button type="button" className="reg-btn" disabled={busy || remaining > 0} onClick={() => run(true)}>{remaining > 0 ? `Новое письмо через ${remaining} с` : 'Отправить код повторно'}</button>
      <button type="button" className="reg-btn" disabled={busy} onClick={onBack}>Вернуться ко входу</button>
    </div>
  </form></div>;
}
