import React, { useState, useEffect, useRef } from 'react';
import './auth.css';
import { t } from '../../utils/i18n';

import { useLocation, useNavigate } from 'react-router-dom';
import { loginUser, STATIC_DEMO } from '../../utils/api';
import EmailConfirmation from './EmailConfirmation';
import { getSessionNotice, getSessionSnapshot, saveToken } from '../../utils/storage';
import { useSession } from './SessionBoundary';

const Auth = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [challenge, setChallenge] = useState(null);
    const pending = useRef(false);
    const mounted = useRef(true);
    const session = useSession();
    useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
    const [, setLangState] = useState(localStorage.getItem('alinavit:comparison:lang') || 'ru');

    const navigate = useNavigate();
    const location = useLocation();

        // re-render component when language changes in header
        useEffect(() => {
            const onLang = () => setLangState(localStorage.getItem('alinavit:comparison:lang') || 'ru');
            window.addEventListener('langchange', onLang);
            return () => window.removeEventListener('langchange', onLang);
        }, []);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (pending.current) return;
        setError('');
        if (!username) {
            setError(t('enter_username'));
            return;
        }
        if (!password) {
            setError(t('enter_password'));
            return;
        }
        try {
            pending.current = true;
            setLoading(true);
            const data = await loginUser(username, password);
            if (!mounted.current || getSessionSnapshot().revision !== session.revision) return;
            if (data.requires_confirmation) { setChallenge(data); return; }
            if (!data.token) {
                setError(t('login_error'));
                return;
            }
            saveToken(data.token);
            navigate('/profile');
        } catch (err) {
                if (process.env.NODE_ENV === 'development') console.error(err);
            if (mounted.current) setError(err.message || t('login_failed'));
        } finally {
            pending.current = false;
            if (mounted.current) setLoading(false);
        }
    };

    if (challenge) return <EmailConfirmation challenge={challenge} onBack={() => setChallenge(null)} onResend={async () => {
        const data = await loginUser(username, password);
        if (mounted.current && getSessionSnapshot().revision === session.revision) setChallenge(data);
    }}/>;
    return (
        <div className="auth-container">
            <form onSubmit={handleSubmit}>
                <h1>{t('login_title')}</h1>
                {STATIC_DEMO && <p className="auth-help">Демоверсия: письма не отправляются, аккаунт хранится только в этом браузере. Не используйте настоящий пароль от других сайтов.</p>}
                {getSessionNotice() && <p role="status" className="auth-error">{getSessionNotice()}</p>}
                {location.state?.logoutWarning && <p role="status" className="auth-error">{location.state.logoutWarning}</p>}
                <div className="input-container">
                    <input
                        type="text"
                        autoComplete="username"
                        id="username"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        required
                    />
                    <label htmlFor="username">Почта или имя пользователя</label>
                    <div className="bar"></div>
                </div>
                <div className="input-container">
                    <input
                        type="password"
                        autoComplete="current-password"
                        id="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                    />
                    <label htmlFor="password">{t('password_label')}</label>
                    <div className="bar"></div>
                </div>
                {error && <div className="auth-error">{error}</div>}
                <div className="button-container">
                    <button type="submit" disabled={loading}>
                        {loading ? 'Входим…' : t('login_btn')}
                    </button>
                    <button type="button" className="reg-btn" onClick={() => navigate('/reg')}>
                        {t('reg_btn')}
                    </button>
                </div>
                <div className="footer">
                    {/* Forgot password temporarily hidden */}
                </div>
            </form>
        </div>
    );
};



export default Auth;

