import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { getSessionNotice } from '../../utils/storage';
import { useSession } from './SessionBoundary';
import './session-notice.css';

export default function SessionNotice() {
  const { token } = useSession();
  const location = useLocation();
  const notice = getSessionNotice();
  if (token || !notice || location.pathname.replace(/\/+$/, '') === '/auth') return null;
  return <section className="session-expiry-notice" role="status">
    <p>{notice}</p>
    <Link to="/auth">Войти снова</Link>
  </section>;
}
