import React, { useEffect, useRef, useState } from 'react';
import { Link, NavLink, useLocation, useNavigate } from 'react-router-dom';
import { ChevronDown, LogOut, Menu, UserRound, X } from 'lucide-react';
import './header.css';
import { logoutCurrentSession } from '../../utils/logout';

export default function Header() {
  const [auth, setAuth] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const logoutPending = useRef(false);
  const headerRef = useRef(null);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    setAuth(!!localStorage.getItem('alinavit:comparison:token'));
    setMobileOpen(false);
    setProfileOpen(false);
  }, [location.pathname]);

  useEffect(() => {
    const close = event => {
      if (headerRef.current && !headerRef.current.contains(event.target)) {
        setMobileOpen(false);
        setProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, []);

  const navClass = ({ isActive }) => `site-nav__link${isActive ? ' is-active' : ''}`;
  const handleLogout = async () => {
    if (logoutPending.current) return;
    logoutPending.current = true;
    setLoggingOut(true);
    const warning = await logoutCurrentSession();
    if (warning !== null) navigate('/auth', { state: { logoutWarning: warning } });
  };

  return (
    <header className="site-header" ref={headerRef}>
      <div className="site-header__inner">
        <Link to="/about" className="brand" aria-label="Внутренний ритм — главная">
          <span className="brand__pulse" aria-hidden="true" />
          <span className="brand__name">Внутренний ритм</span>
          <span className="brand__note">Алина Сумеркина</span>
        </Link>

        <nav className={`site-nav${mobileOpen ? ' is-open' : ''}`} aria-label="Основная навигация">
          <NavLink to="/about" className={navClass}>Главная</NavLink>
          <NavLink to="/courses/buy" className={navClass}>Программы</NavLink>
          <Link to="/about#method" className="site-nav__link">Методика</Link>
          <Link to="/about#journey" className="site-nav__link">5 месяцев</Link>
          {auth && <NavLink to="/courses/pass" className={navClass}>Мои занятия</NavLink>}
          {auth && <NavLink to="/diary" className={navClass}>Дневник</NavLink>}
          <NavLink to="/support" className={navClass}>Участие</NavLink>
          {!auth && <NavLink to="/auth" className="site-nav__link mobile-login">Войти / зарегистрироваться</NavLink>}
        </nav>

        <div className="site-header__actions">
          {!auth ? (
            <>
              <Link to="/auth" className="header-login">Войти</Link>
              <Link to="/support" className="header-start">Узнать об участии</Link>
            </>
          ) : (
            <div className="account-menu">
              <button type="button" className="header-account" onClick={() => setProfileOpen(value => !value)} aria-expanded={profileOpen} aria-haspopup="menu">
                <UserRound size={18} /><span>Кабинет</span><ChevronDown size={15} />
              </button>
              <div className={`account-popover${profileOpen ? ' is-open' : ''}`} hidden={!profileOpen}>
                <Link to="/profile" className="account-popover__primary"><strong>Личный кабинет</strong><small>Этап, практики и настройки</small></Link>
                <button className="account-popover__logout" disabled={loggingOut} onClick={handleLogout}><LogOut size={16} /> {loggingOut ? 'Выходим…' : 'Выйти'}</button>
              </div>
            </div>
          )}
          <button type="button" className="mobile-menu-btn" onClick={() => setMobileOpen(value => !value)} aria-expanded={mobileOpen} aria-label={mobileOpen ? 'Закрыть меню' : 'Открыть меню'}>{mobileOpen ? <X size={22} /> : <Menu size={22} />}</button>
        </div>
      </div>
    </header>
  );
}
