export const STATIC_DEMO = process.env.REACT_APP_STATIC_DEMO === 'true';

export async function logoutUser(token) {
  if (STATIC_DEMO || !token) return;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 8000);
  try {
    const response = await fetch(buildUrl('/auth/logout'), {
      method: 'POST', cache: 'no-store', signal: controller.signal,
      headers: { Authorization: `Bearer ${token}` },
    });
    // Already-invalid credentials cannot authorize requests either.
    if (!response.ok && response.status !== 401) throw new Error('Не удалось подтвердить выход на сервере.');
  } finally { clearTimeout(timeout); }
}

function joinBase(base, path) {
  return base.replace(/\/+$/, '') + (path.startsWith('/') ? path : '/' + path);
}

function readEnv(name) {
  const value = process.env[name];
  return value && value.trim() !== '' ? value.trim() : '';
}

function getBaseApi() {
  const explicitApi = readEnv('REACT_APP_BACKEND_API') || readEnv('REACT_APP_PAYMENT_API');
  if (explicitApi) return explicitApi.replace(/\/+$/, '');

  const backendDomain = readEnv('REACT_APP_BACKEND_DOMAIN');
  const apiPath = readEnv('REACT_APP_BACKEND_API_PATH') || '/api';
  if (backendDomain) return joinBase(backendDomain, apiPath);

  return '/api'; // default through nginx proxy
}

const BASE_API = getBaseApi();

function buildUrl(path) {
  return joinBase(BASE_API, path);
}

async function _fetchJson(url, options) {
  // Do not share in-flight responses: the same URL can belong to a different
  // account, or be reloaded after a write while an older read is still pending.
  const res = await sessionFetch(url, options);
  if (!res.ok) {
    const error = new Error(`Ошибка: ${res.status}`);
    error.status = res.status;
    throw error;
  }
  return await res.json();
}

// API функции
async function researchFormRequest(token, path = '', method = 'GET', body) {
  if (STATIC_DEMO) {
    const error = new Error('Серверный конструктор не подключён к демоверсии.');
    error.status = 503;
    throw error;
  }
  return _fetchJson(buildUrl(`/admin/research-forms${path}`), {
    method,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  });
}
export const fetchResearchForms = token => researchFormRequest(token);
export const fetchResearchForm = (token, id) => researchFormRequest(token, `/${encodeURIComponent(id)}`);
export const saveResearchForm = (token, definition, id, revision) => id
  ? researchFormRequest(token, `/${encodeURIComponent(id)}`, 'PUT', { definition, expected_revision: revision })
  : researchFormRequest(token, '', 'POST', { definition });
export const freezeResearchForm = (token, id, revision) => researchFormRequest(token, `/${encodeURIComponent(id)}/versions`, 'POST', { expected_revision: revision });
export const fetchResearchFormVersions = (token, id) => researchFormRequest(token, `/${encodeURIComponent(id)}/versions`);
export const fetchResearchFormAudit = (token, id, before = 0) => researchFormRequest(token, `/${encodeURIComponent(id)}/audit${before ? `?before=${encodeURIComponent(before)}` : ''}`);

export async function fetchUserbyToken(token) {
  if (STATIC_DEMO) return demoGetUser(token);
  return _fetchJson(buildUrl('/users/me'), {
    headers: { 'Authorization': `Bearer ${token}` },
  });
}

export async function createUser(userData) {
  if (STATIC_DEMO) return demoRegister(userData);
  try { return await _fetchJson(buildUrl('/auth/register'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(userData),
  }); } catch (error) {
    if (error.status === 409) throw new Error('Это имя пользователя или email уже используется. Выберите другое имя или адрес.');
    if (error.status === 503) throw new Error('Отправка писем временно недоступна. Если аккаунт уже создан, попробуйте войти через минуту.');
    if (error.status === 400) throw new Error('Проверьте почту, имя и пароль (не менее 8 символов).');
    throw error;
  }
}

