export async function updateCourseProgress(token, courseId, viewed, completed, viewedKeys) {
  if (STATIC_DEMO) return demoUpdateProgress(token, courseId, viewed, completed, viewedKeys);
  const res = await sessionFetch(buildUrl('/users/me/progress'), {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
    },
    body: JSON.stringify({ course_id: courseId, viewed, completed, viewed_keys: viewedKeys }),
  });
  if (!res.ok) throw new Error(res.status === 409 ? 'Программа изменилась. Обновите страницу перед сохранением.' : `Не удалось сохранить прогресс: ${res.status}`);
}

