export default api;
export { buildUrl };

export async function loginUser(username, password) {
  if (STATIC_DEMO) return demoLogin(username, password);
  return authRequest('/auth/login', { username: username.trim(), password });
}

async function authRequest(path, body) {
  try { return await _fetchJson(buildUrl(path), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }); } catch (error) {
    const messages = { 400: 'Код неверен или истёк. Проверьте его или запросите новый.', 401: 'Неверная почта, имя пользователя или пароль.', 403: 'Для этого аккаунта нужно настроить почту. Обратитесь в поддержку.', 429: 'Слишком частые запросы. Подождите минуту и попробуйте снова.', 503: 'Вход или отправка писем временно недоступны. Если аккаунт уже создан, попробуйте войти позднее.' };
    throw new Error(messages[error.status] || 'Не удалось выполнить вход. Проверьте соединение и повторите.');
  }
}

export async function confirmEmailLogin(challengeId, code) {
  if (STATIC_DEMO) throw new Error('В демоверсии подтверждение почты не подключено.');
  return authRequest('/auth/confirm', { challenge_id: challengeId, code });
}
