export function t(key, vars = {}) {
  try {
    const lang = (localStorage.getItem('alinavit:comparison:lang') || 'ru');
    const msg = (DICT[lang] && DICT[lang][key]) || DICT['ru'][key] || key;
    return Object.keys(vars).reduce((acc,k) => acc.replace(`{${k}}`, vars[k]), msg);
  } catch (e) {
    return key;
  }
}

const i18n = {
  t
};

export default i18n;
