// Ключи для localStorage
export const STORAGE_KEYS = {
    THEME: 'alinavit:comparison:app-theme',
    USER: 'alinavit:comparison:user',
    AUTH_TOKEN: 'alinavit:comparison:token',
    SESSION_NOTICE: 'alinavit:comparison:session-notice',
};

// Функции для работы с темой
export const saveTheme = (theme) => {
    localStorage.setItem(STORAGE_KEYS.THEME, theme);
};

export const getTheme = () => {
    return localStorage.getItem(STORAGE_KEYS.THEME) || 'light';
};

// Функции для работы с пользователем
export const saveUser = (user) => {
    localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(user));
};

export const getUser = () => {
    const user = localStorage.getItem(STORAGE_KEYS.USER);
    return user ? JSON.parse(user) : null;
};

// Функции для работы с токеном
export const saveToken = (token) => {
    if (typeof token !== 'string' || !token.trim()) throw new Error('Сессия не получена. Попробуйте войти снова.');
    localStorage.removeItem(STORAGE_KEYS.USER);
    localStorage.removeItem(STORAGE_KEYS.SESSION_NOTICE);
    localStorage.setItem(STORAGE_KEYS.AUTH_TOKEN, token);
    publishSessionChange();
};

export const getToken = () => {
    return localStorage.getItem(STORAGE_KEYS.AUTH_TOKEN);
};

export const clearUserData = () => {
    localStorage.removeItem(STORAGE_KEYS.SESSION_NOTICE);
    localStorage.removeItem(STORAGE_KEYS.USER);
    localStorage.removeItem(STORAGE_KEYS.AUTH_TOKEN);
    publishSessionChange();
};

export const SESSION_EXPIRED_MESSAGE = 'Ваш вход завершён. Пожалуйста, войдите снова. Несохранённые изменения могли не сохраниться.';
export const getSessionNotice = () => localStorage.getItem(STORAGE_KEYS.SESSION_NOTICE) === 'expired' ? SESSION_EXPIRED_MESSAGE : '';

export const expireSession = (expected) => {
    const current = getSessionSnapshot();
    if (!expected.token || current.token !== expected.token || current.revision !== expected.revision) return false;
    localStorage.setItem(STORAGE_KEYS.SESSION_NOTICE, 'expired');
    localStorage.removeItem(STORAGE_KEYS.USER);
    localStorage.removeItem(STORAGE_KEYS.AUTH_TOKEN);
    publishSessionChange();
    return true;
};

let snapshot = { token: null, revision: 0 };
const publishSessionChange = () => {
    snapshot = { token: getToken(), revision: snapshot.revision + 1 };
    window.dispatchEvent(new Event('sessionchange'));
};
export const getSessionSnapshot = () => {
    const token = getToken();
    if (snapshot.token !== token) snapshot = { token, revision: snapshot.revision + 1 };
    return snapshot;
};

let lastStorageEvent;
export const subscribeSession = (notify) => {
    const onStorage = event => {
        if (event.storageArea && event.storageArea !== localStorage) return;
        if (event.key === null || event.key === STORAGE_KEYS.AUTH_TOKEN) {
            // One external event may reach multiple subscribers. Advance once
            // even if an account switched away and back before events ran.
            if (lastStorageEvent !== event) {
                lastStorageEvent = event;
                snapshot = { token: getToken(), revision: snapshot.revision + 1 };
            }
            notify();
        }
    };
    window.addEventListener('sessionchange', notify);
    window.addEventListener('storage', onStorage);
    window.addEventListener('pageshow', notify);
    return () => {
        window.removeEventListener('sessionchange', notify);
        window.removeEventListener('storage', onStorage);
        window.removeEventListener('pageshow', notify);
    };
};
