import React, { useEffect, useRef, useState } from 'react';
import './reg.css';
import { useNavigate } from 'react-router-dom';
import { createUser, loginUser, STATIC_DEMO } from '../../utils/api';
import EmailConfirmation from '../Auth/EmailConfirmation';
import { getSessionSnapshot, saveToken } from '../../utils/storage';
import { useSession } from '../Auth/SessionBoundary';

const Reg = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');
  const [challenge, setChallenge] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const session = useSession();
  const mounted = useRef(true);
  const pending = useRef(false);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (pending.current) return;
    setLoading(true);
    setError('');

    if (!username.trim() || !password || !email.trim()) {
      setError('Введите имя, почту и пароль');
      setLoading(false);
      return;
    }

    const userData = {
      username: username,
      password: password,
      email: email.trim(),
    };

    try {
      pending.current = true;
      const res = await createUser(userData);
      if (!mounted.current || getSessionSnapshot().revision !== session.revision) return;
      if (res.requires_confirmation) { setChallenge(res); return; }
      saveToken(res.token);
      navigate('/profile');
    } catch (err) {
      if (mounted.current) setError(err.message);
    } finally {
      pending.current = false;
      if (mounted.current) setLoading(false);
    }
  };

  if (challenge) return <EmailConfirmation challenge={challenge} onBack={() => navigate('/auth')} onResend={async () => {
    const data = await loginUser(email.trim(), password);
    if (mounted.current && getSessionSnapshot().revision === session.revision) setChallenge(data);
  }}/>;
  return (
    <div className="reg-container">
      <form onSubmit={handleSubmit} className="reg-form">
        <h1>Регистрация</h1>
        {STATIC_DEMO && <p className="auth-help">Это демоверсия без отправки писем. Используйте тестовую почту и отдельный тестовый пароль. Данные останутся в этом браузере.</p>}
        <div className="input-container">
          <input type="email" id="email" autoComplete="email" value={email} onChange={event => setEmail(event.target.value)} maxLength={254} required/>
          <label htmlFor="email">Электронная почта</label>
        </div>
        <div className="input-container">
          <input
            type="text"
            autoComplete="username"
            id="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
          <label htmlFor="username">Имя пользователя</label>
          <div className="bar"></div>
        </div>
        <div className="input-container">
          <input
          type="password"
            autoComplete="new-password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            minLength={8}
          />
          <label htmlFor="password">Пароль</label>
          <div className="bar"></div>
        </div>
        <div className="button-container">
          <button type="submit" disabled={loading}>
            {loading ? 'Регистрация...' : 'Зарегистрироваться'}
          </button>
        </div>
        {error && <div className="reg-error">{error}</div>}
      </form>
    </div>
  );
};

export default Reg;
