import React, { useCallback, useEffect, useRef, useState } from 'react';
import { fetchResearchFormAudit } from '../../utils/api';

const actionNames = { draft_created: 'Создан черновик', draft_updated: 'Сохранён черновик', version_frozen: 'Зафиксирована версия' };
const dateLabel = value => {
  const date = new Date(value);
  return value && Number.isFinite(date.getTime())
    ? date.toLocaleString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })
    : 'Дата не указана';
};

// The parent keys this view by account and form. A request generation also
// prevents an older refresh/page response from replacing a newer result.
export default function ResearchFormAudit({ token, formId, connected, refreshKey, onAccessLost }) {
  const [open, setOpen] = useState(false);
  const [page, setPage] = useState(null);
  const [cursors, setCursors] = useState([0]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [refresh, setRefresh] = useState(0);
  const generation = useRef(0);
  const pending = useRef(false);
  const attemptedCursors = useRef([0]);

  const load = useCallback(async (nextCursors) => {
    if (pending.current) return;
    pending.current = true;
    attemptedCursors.current = nextCursors;
    const request = ++generation.current;
    setLoading(true); setError('');
    try {
      const result = await fetchResearchFormAudit(token, formId, nextCursors[nextCursors.length - 1]);
      if (request !== generation.current) return;
      // A malformed response is an error, never an apparently empty journal.
      if (!result || !Array.isArray(result.entries) || result.entries.length > 50 || result.entries.some(entry => !entry || entry.form_id !== formId || !Number.isSafeInteger(entry.id) || entry.id < 1) || (result.next_before != null && (!Number.isSafeInteger(result.next_before) || result.next_before < 0))) throw new Error('Invalid audit page');
      setPage(result); setCursors(nextCursors);
    } catch (failure) {
      if (request !== generation.current) return;
      if (failure.status === 401 || failure.status === 403) {
        setPage(null); onAccessLost(failure.status);
      } else {
        setError(failure.status === 404 ? 'Журнал этой формы недоступен. Проверьте подключение к серверному разделу.' : 'Не удалось загрузить журнал. Сохранение анкеты этим не отменяется. Повторите загрузку.');
      }
    } finally {
      if (request === generation.current) { pending.current = false; setLoading(false); }
    }
  }, [token, formId, onAccessLost]);

  useEffect(() => {
    setPage(null); setCursors([0]); setError(''); setLoading(false);
    if (open && connected && formId) load([0]);
    return () => { generation.current += 1; pending.current = false; };
  }, [open, connected, formId, refreshKey, refresh, load]);

  const available = connected && !!formId;
  return <section className="research-audit" aria-label="Журнал изменений анкеты">
    <div className="research-audit__header">
      <div><h2>История изменений</h2><p className="research-note">Кто и когда сохранил черновик или зафиксировал версию.</p></div>
      {available && <button type="button" aria-expanded={open} aria-controls="research-audit-content" onClick={() => setOpen(value => !value)}>{open ? 'Скрыть журнал' : 'Показать журнал'}</button>}
    </div>
    {!connected ? <p className="research-note">Журнал доступен только на подключённом сервере. В демоверсии история действий не создаётся.</p>
      : !formId ? <p className="research-note">Сначала сохраните новую форму на сервере — после этого появится её журнал.</p> : null}
    {available && open && <div id="research-audit-content" aria-busy={loading}>
      <p className="research-note">Имена указаны на момент действия, время — по часовому поясу устройства. Записи до подключения журнала могут отсутствовать. Фиксация версии не означает публикацию участникам.</p>
      {loading && <p role="status">Загружаем журнал…</p>}
      {error && <p className="research-message" role="alert">{error}</p>}
      {page && <>
        <p className="research-note" role="status">Страница {cursors.length} · записей: {page.entries.length}{page.next_before ? ' · есть более ранние' : ' · конец доступной истории'}</p>
        {page.entries.length === 0 ? <p>Записей в журнале пока нет. Это не означает, что анкету никогда не меняли.</p> : <ol className="research-audit__list" aria-label="События журнала">
          {page.entries.map(entry => <li key={entry.id}>
            <div><strong>{actionNames[entry.action] || 'Неизвестное действие'}</strong><span>Ревизия {entry.revision}</span></div>
            <div><span className="research-audit__label">Автор</span><span>{entry.actor_name || 'Имя не указано'}</span><details><summary>Код автора</summary><code>{entry.actor_ref}</code></details></div>
            <time dateTime={Number.isFinite(new Date(entry.occurred_at).getTime()) ? entry.occurred_at : undefined}>{dateLabel(entry.occurred_at)}</time>
          </li>)}
        </ol>}
      </>}
      <div className="research-audit__actions">
        <button type="button" disabled={loading} onClick={() => setRefresh(value => value + 1)}>Обновить журнал</button>
        {error && <button type="button" disabled={loading} onClick={() => load(attemptedCursors.current)}>Повторить загрузку</button>}
        {page && cursors.length > 1 && <button type="button" disabled={loading} onClick={() => load(cursors.slice(0, -1))}>Более новые записи</button>}
        {page?.next_before > 0 && <button type="button" disabled={loading} onClick={() => load([...cursors, page.next_before])}>Более ранние записи</button>}
      </div>
    </div>}
  </section>;
}
