import React, { useEffect, useRef, useState } from 'react';
import { useParams } from 'react-router-dom';
import { fetchUserCourses } from '../../../utils/api';
import { fetchUserbyToken, updateCourseProgress } from '../../../utils/api';
import { useSession } from '../../../components/Auth/SessionBoundary';
import { getSessionSnapshot } from '../../../utils/storage';
import { checkpointScheduleLabel } from '../../../utils/checkpointSchedule';
import { projectCourseProgress, progressKeyArgs } from '../../../utils/courseProgress';
import '../../Courses/courses.css';
import './CourseDetail.css';

function getYouTubeId(url) {
  // Простая экстракция ID из разных форматов ссылок
  if (!url) return null;
  const reg = /(?:v=|\/embed\/|youtu.be\/|\/v\/|watch\?v=)([A-Za-z0-9_-]{11})/;
  const m = url.match(reg);
  return m ? m[1] : null;
}

function lessonSuffixes(lesson) {
  return Array.isArray(lesson?.suffixes)
    ? lesson.suffixes.filter(Boolean)
    : [];
}

const CourseDetail = () => {
	const session = useSession();
	const token = session.token;
	const { id } = useParams();
	const [course, setCourse] = useState(null);
	const [loading, setLoading] = useState(true);
	const [error, setError] = useState('');
  const [activeExercise, setActiveExercise] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(typeof window !== 'undefined' ? window.innerWidth <= 820 : false);
  const [viewed, setViewed] = useState(new Set());
  const [checkpointStatus, setCheckpointStatus] = useState('');
  const [savingStep, setSavingStep] = useState(false);
  const [progressRetry, setProgressRetry] = useState(0);
  const savingRef = useRef(false);
  const currentCourseId = useRef(id);
  currentCourseId.current = id;

  const lessons = course ? (course.sourcesToExercises || course.SourcesToExercises || []) : [];

	useEffect(() => {
		let cancelled = false;
		setLoading(true);
		setError('');
		setCourse(null);
		setActiveExercise(null);
		setViewed(new Set());
		setCheckpointStatus('');
		if (!token) {
			setError('Необходимо войти в аккаунт');
			setLoading(false);
			return;
		}
		Promise.all([fetchUserCourses(token), fetchUserbyToken(token)])
			.then(([courses, user]) => {
				if (cancelled) return;
				const ownedCourse = Array.isArray(courses)
					? courses.find(c => Number(c.id) === Number(id))
					: null;
				if (!ownedCourse) throw new Error('Программа не добавлена или не найдена');
				setCourse(ownedCourse);
				setViewed(new Set(projectCourseProgress(ownedCourse, user.progress_course?.[ownedCourse.id]).viewed));
			})
			.catch(e => { if (!cancelled) setError(e.message); })
			.finally(() => { if (!cancelled) setLoading(false); });
		return () => { cancelled = true; };
	}, [id, token]);

  useEffect(() => {
    const onResize = () => setIsMobile(window.innerWidth <= 820);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  // Когда курс загружен и уроки есть — по умолчанию выбрать первый урок (если не выбран)
  useEffect(() => {
    if (course) {
      const lessons = course.sourcesToExercises || course.SourcesToExercises || [];
      if (lessons.length > 0 && activeExercise === null) {
        setActiveExercise(0);
      }
    }
  }, [course, activeExercise]);

  // A visible checkmark means the server accepted this exact lesson, not merely
  // that an old array index was opened. Failed writes remain retryable.
  useEffect(() => {
    if (activeExercise == null || !course || String(course.id) !== id || course.content_type === 'checkpoint' || !token) return;
    let cancelled = false;
    const idx = activeExercise;
    setCheckpointStatus('');
    (async () => {
      try {
        const user = await fetchUserbyToken(token);
        if (cancelled || getSessionSnapshot().revision !== session.revision) return;
        const existing = Array.from(new Set([...projectCourseProgress(course, user.progress_course?.[course.id]).viewed, idx]));
        await updateCourseProgress(token, course.id, existing, existing.length >= lessons.length, ...progressKeyArgs(course, [idx]));
        if (cancelled || getSessionSnapshot().revision !== session.revision) return;
        setViewed(previous => new Set([...previous, ...existing]));
      } catch (saveError) {
        if (!cancelled && getSessionSnapshot().revision === session.revision) setCheckpointStatus(saveError.message || 'Не удалось сохранить просмотр. Попробуйте ещё раз.');
      }
    })();
    return () => { cancelled = true; };
  }, [activeExercise, course, id, lessons.length, token, session.revision, progressRetry]);
  const completeCheckpointStep = async () => {
    if (activeExercise == null || !course || savingRef.current) return;
    if (!token || getSessionSnapshot().revision !== session.revision) return;
    savingRef.current = true;
    setSavingStep(true);
    const requestedCourseId = id;
    const idx = activeExercise;
    const nextViewed = Array.from(new Set([...viewed, idx]));
    setCheckpointStatus('Сохраняем выполнение…');
    try {
      await updateCourseProgress(token, course.id, nextViewed, nextViewed.length >= lessons.length, ...progressKeyArgs(course, [idx]));
      if (currentCourseId.current !== requestedCourseId || getSessionSnapshot().revision !== session.revision) return;
      setViewed(new Set(nextViewed));
      setCheckpointStatus(nextViewed.length >= lessons.length ? 'Контрольная точка пройдена.' : 'Шаг отмечен выполненным.');
    } catch (completionError) {
      if (currentCourseId.current === requestedCourseId) setCheckpointStatus(`${completionError.message || 'Не удалось сохранить выполнение.'} Попробуйте ещё раз.`);
    } finally {
      savingRef.current = false;
      setSavingStep(false);
    }
  };

	if (loading) return <div className="common-page-card">Загрузка...</div>;
	if (error) return <div className="common-page-card">Ошибка: {error}</div>;
	if (!course) return <div className="common-page-card">Программа не найдена</div>;

  const selected = typeof activeExercise === 'number' ? lessons[activeExercise] : null;
  const isCheckpoint = course.content_type === 'checkpoint';

  // defensive: some JSON files may have inconsistent key names (typos, different casing)
  // find first property that looks like a source URL (contains 'sour' in key name)
  let selectedSource = null;
  if (selected) {
    if (selected.source && typeof selected.source === 'string') selectedSource = selected.source;
    else {
      for (const k of Object.keys(selected)) {
        if (k.toLowerCase().includes('sour') && typeof selected[k] === 'string') {
          selectedSource = selected[k];
          break;
        }
      }
    }
  }
  const ytId = selectedSource ? getYouTubeId(selectedSource) : null;
  const progressPercent = lessons.length ? Math.round((viewed.size / lessons.length) * 100) : 0;

  return (
    <div className={`common-page-card course-detail-root ${sidebarOpen? 'sidebar-open':''}${isCheckpoint ? ' is-checkpoint' : ''}`}>
      {/* Mobile: toggle for lessons sidebar */}
      <button className="course-sidebar-toggle" onClick={() => setSidebarOpen(s => !s)} aria-expanded={sidebarOpen}>
        {sidebarOpen ? 'Закрыть список' : isCheckpoint ? 'Шаги' : 'Практики'}
      </button>
      <div className="course-detail-row">
      {/* Левая часть: видео выбранного урока или пусто */}
      <div className="course-detail-left">
        <span className="course-detail-kicker">{isCheckpoint ? `Контрольная точка · ${checkpointScheduleLabel(course)}` : 'Ваш практический трек'}</span>
        <h1 className="common-title course-detail-title">{course.title}</h1>
        <div className="course-detail-meta">
          <span>{lessons.length} {isCheckpoint ? (lessons.length === 1 ? 'шаг' : lessons.length < 5 ? 'шага' : 'шагов') : 'занятий'}</span>
          <span>{progressPercent}% пройдено</span>
        </div>
        <div className="course-progress" aria-label={`Пройдено ${progressPercent}%`}><span style={{ width: `${progressPercent}%` }} /></div>
        {isMobile && sidebarOpen ? (
          <div className="course-detail-selected">
            <h3>Список практик</h3>
            <div className="course-detail-lessons-list">
              {lessons.length > 0 ? lessons.map((lesson, idx) => (
                <div
                  key={lesson.lesson_key || lesson.id}
                  className={`course-lesson-item${activeExercise === idx ? ' selected' : ''}`}
                  onClick={() => { setActiveExercise(idx); setSidebarOpen(false); }}
                >
                  <span className="lesson-title">{lesson.title || `Практика ${idx + 1}`}</span>
                  {lesson.isWarmup && <span className="lesson-type">(разминка)</span>}
                  {lesson.isFinal && <span className="lesson-type">(финал)</span>}
                  {lessonSuffixes(lesson).map(suffix => (
                    <span key={suffix} className="lesson-type">({suffix})</span>
                  ))}
                  {viewed.has(idx) && <span className="lesson-status" aria-label="Просмотрено">✓</span>}
                </div>
              )) : <div>Нет практик</div>}
            </div>
          </div>
        ) : selected ? (
          <div className="course-detail-selected">
            <h3>{selected.title || `Практика ${activeExercise + 1}`}</h3>
            {ytId ? (
              <div className="course-detail-video-wrapper">
                <iframe
                  className="course-detail-iframe"
                  title={`video-${selected.id}`}
                  src={`https://www.youtube.com/embed/${ytId}`}
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                />
              </div>
            ) : <div style={{ marginBottom: 16 }}>{isCheckpoint ? 'Выполните шаг по инструкции ниже.' : 'Для этой практики пока нет видео'}</div>}
            <div className="course-detail-video-info">
              {selected.isWarmup && <span style={{ marginRight: 12 }}>(разминка)</span>}
              {selected.isFinal && <span>(финал)</span>}
              {lessonSuffixes(selected).map(suffix => (
                <span key={suffix} style={{ marginLeft: 12 }}>({suffix})</span>
              ))}
            </div>
            {selected.description && <p className="course-detail-step-description">{selected.description}</p>}
            {isCheckpoint && <div className="checkpoint-completion"><button type="button" disabled={savingStep || viewed.has(activeExercise)} onClick={completeCheckpointStep}>{savingStep ? 'Сохраняем…' : viewed.has(activeExercise) ? 'Шаг выполнен' : 'Отметить шаг выполненным'}</button>{checkpointStatus && <span role="status">{checkpointStatus}</span>}</div>}
            {!isCheckpoint && checkpointStatus && <div className="checkpoint-completion"><span role="status">{checkpointStatus}</span><button type="button" onClick={() => setProgressRetry(value => value + 1)}>Повторить сохранение</button></div>}
          </div>
        ) : null}
      </div>
  {/* Правая часть: скроллируемый список уроков */}
  {!isMobile && (
    <div className="course-detail-right">
      <div className="course-detail-right__heading"><span>Содержание</span><small>{viewed.size}/{lessons.length}</small></div>
      <div className="course-detail-lessons-list">
        {lessons.length > 0 ? lessons.map((lesson, idx) => (
          <div
            key={lesson.lesson_key || lesson.id}
            className={`course-lesson-item${activeExercise === idx ? ' selected' : ''}`}
            onClick={() => setActiveExercise(idx)}
          >
            <span className="lesson-title">{lesson.title || `Практика ${idx + 1}`}</span>
            {lesson.isWarmup && <span className="lesson-type">(разминка)</span>}
            {lesson.isFinal && <span className="lesson-type">(финал)</span>}
            {lessonSuffixes(lesson).map(suffix => (
              <span key={suffix} className="lesson-type">({suffix})</span>
            ))}
            {viewed.has(idx) && <span className="lesson-status" aria-label="Просмотрено">✓</span>}
          </div>
        )) : <div>Нет практик</div>}
      </div>
    </div>
  )}
      </div>
      <div className="course-detail-bottom">
        <div className="course-detail-bottom-inner">
          <p className="common-desc">{course.description}</p>
          {isCheckpoint && course.checkpoint_note && <p className="course-detail-checkpoint-note">{course.checkpoint_note}</p>}
        </div>
      </div>
    </div>
  );
};

export default CourseDetail;
