import React from 'react';
import { Link } from 'react-router-dom';
import './footer.css';

const Footer = () => (
  <footer className="site-footer">
    <div className="footer-container">
      <div className="footer-brand">
        <strong>Внутренний ритм</strong>
        <span>Исследовательско-практическая программа Алины Сумеркиной</span>
      </div>
      <nav className="footer-links" aria-label="Правовая информация">
        <Link to="/terms">Условия использования</Link>
        <Link to="/privacy">Конфиденциальность</Link>
        <Link to="/yookassa-ip">Реквизиты</Link>
      </nav>
      <div className="footer-meta">
        <span>ИП Сумеркина Алина Владимировна</span>
        <span>© {new Date().getFullYear()}</span>
      </div>
    </div>
  </footer>
);

export default Footer;
