import React, { useId, useMemo, useState } from 'react';
import { ChevronLeft, ChevronRight, Trash2 } from 'lucide-react';
import './diary-history.css';

const labels = ['Очень тихий', 'Сбавленный', 'Ровный', 'Живой', 'Наполненный'];
const PAGE_SIZE = 10;
const toDate = value => {
  if (value === null || value === undefined || value === '') return null;
  const date = new Date(typeof value === 'number' ? value * 1000 : value);
  return Number.isNaN(date.getTime()) ? null : date;
};
const monthKey = date => date ? `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}` : '';

export default function DiaryHistory({ entries, onClear, busy = false }) {
  const id = useId();
  const [expanded, setExpanded] = useState(false);
  const [month, setMonth] = useState('');
  const [page, setPage] = useState(0);
  const ordered = useMemo(() => entries.map(entry => ({ ...entry, date: toDate(entry.created_at) }))
    .sort((a, b) => (b.date?.getTime() ?? -Infinity) - (a.date?.getTime() ?? -Infinity)), [entries]);
  const months = useMemo(() => Array.from(new Map(ordered.filter(entry => entry.date)
    .map(entry => [monthKey(entry.date), entry.date.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' })]))), [ordered]);
  const selectedMonth = months.some(([key]) => key === month) ? month : '';
  const filtered = selectedMonth ? ordered.filter(entry => monthKey(entry.date) === selectedMonth) : ordered;
  const pages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pages - 1);
  const visible = expanded ? filtered.slice(currentPage * PAGE_SIZE, (currentPage + 1) * PAGE_SIZE) : ordered.slice(0, 3);

  return (
    <section className="diary-history" aria-labelledby={`${id}-title`}>
      <div className="diary-history__heading">
        <div><h3 id={`${id}-title`}>Дневник наблюдений</h3><p>Сохранено отметок: {entries.length}. Это ваши личные наблюдения, не оценка здоровья.</p></div>
        {entries.length > 3 && <button type="button" aria-expanded={expanded} aria-controls={`${id}-content`} onClick={() => { setExpanded(!expanded); setPage(0); }}>
          {expanded ? 'Свернуть историю' : 'Посмотреть всю историю'}
        </button>}
      </div>
      <div id={`${id}-content`}>
        {expanded && entries.length > 0 && <div className="diary-history__filter">
          <label htmlFor={`${id}-month`}>Месяц наблюдений</label>
          <select id={`${id}-month`} value={selectedMonth} onChange={event => { setMonth(event.target.value); setPage(0); }}>
            <option value="">Вся программа</option>
            {months.map(([key, label]) => <option key={key} value={key}>{label}</option>)}
          </select>
        </div>}
        {entries.length === 0 ? <p className="diary-history__empty">Пока нет отметок. Начните с короткой заметки о сегодняшнем дне.</p> : <>
          <p className="diary-history__count" role="status">{expanded ? `Показаны ${currentPage * PAGE_SIZE + 1}–${Math.min((currentPage + 1) * PAGE_SIZE, filtered.length)} из ${filtered.length}` : 'Последние отметки'}</p>
          <ol className="diary-history__list" aria-label="Личные отметки">
            {visible.map((entry, index) => <li key={`${entry.id}-${index}`}>
              <div>{entry.date ? <time dateTime={entry.date.toISOString()}>{entry.date.toLocaleString('ru-RU', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })}</time> : <span>Дата не указана</span>}
                <strong>{labels[entry.rhythm - 1] || 'Без оценки'}</strong></div>
              {entry.note && <p>{entry.note}</p>}
            </li>)}
          </ol>
          {expanded && pages > 1 && <nav className="diary-history__pages" aria-label="Страницы дневника">
            <button type="button" disabled={currentPage === 0} onClick={() => setPage(currentPage - 1)}><ChevronLeft size={16} aria-hidden="true"/> Новее</button>
            <span>Страница {currentPage + 1} из {pages}</span>
            <button type="button" disabled={currentPage === pages - 1} onClick={() => setPage(currentPage + 1)}>Раньше <ChevronRight size={16} aria-hidden="true"/></button>
          </nav>}
          <div className="diary-history__clear"><p>Очистка удалит все отметки, включая записи за другие месяцы.</p><button type="button" disabled={busy} onClick={onClear}><Trash2 size={16} aria-hidden="true"/> Очистить весь дневник</button></div>
        </>}
      </div>
    </section>
  );
}
