import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { ArrowRight, CircleGauge, Compass, Settings } from 'lucide-react';
import { fetchUserbyToken } from '../../utils/api';
import './courses.css';

const Courses = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const token = localStorage.getItem('alinavit:comparison:token');

  useEffect(() => {
    if (!token) return;
    fetchUserbyToken(token)
      .then(user => setIsAdmin(!!(user?.is_admin || user?.isAdmin || user?.Is_Admin)))
      .catch(() => setIsAdmin(false));
  }, [token]);

  return (
    <section className="courses-hub">
      <span className="eyebrow">Платформа участника</span>
      <h1>Ваш следующий небольшой шаг</h1>
      <div className="courses-hub__grid">
        <Link to="/courses/buy"><Compass/><div><h2>Библиотека практик</h2><p>Выберите подходящий трек и добавьте его в свой ритм.</p></div><ArrowRight/></Link>
        <Link to="/courses/pass"><CircleGauge/><div><h2>Мой ритм</h2><p>Посмотрите текущий этап, личную динамику и продолжите практику.</p></div><ArrowRight/></Link>
        {isAdmin && <Link to="/admin/courses-editor"><Settings/><div><h2>Управление платформой</h2><p>Редактирование программ, занятий и условий доступа.</p></div><ArrowRight/></Link>}
      </div>
    </section>
  );
};

export default Courses;
