import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { fetchCourses, STATIC_DEMO } from '../../../utils/api';
import CourseCard from '../../../components/Courses/Course-card';
import PaymentModal from '../../../components/Payment/PaymentModal';
import { createPayment } from '../../../utils/payment';
import './courses-buy.css';

const BuyCourses = () => {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError('');
    // prevent duplicate state updates during StrictMode (dev) or if unmounted
    fetchCourses()
      .then(data => { if (mounted) setCourses(Array.isArray(data) ? data : []); })
      .catch(() => { if (mounted) setError('Не удалось загрузить программы. Проверьте соединение и попробуйте ещё раз.'); })
      .finally(() => { if (mounted) setLoading(false); });
    return () => { mounted = false; };
  }, [reloadKey]);

  const navigate = useNavigate();

  const handleBuy = (courseId) => {
    const token = localStorage.getItem('alinavit:comparison:token');
    if (!token) {
      setError('Войдите в аккаунт, чтобы добавить программу');
      navigate('/auth');
      return;
    }
    // Проверка повторного доступа должна выполняться на сервере оплаты.
    // В тестовом режиме операция идемпотентна и не создаёт дубликаты.
    setError('');
    setActivePurchase(courseId);
  };

  // Оплата
  const [activePurchase, setActivePurchase] = useState(null);

  const doPay = async (explicitCourseId) => {
    const purchaseId = explicitCourseId ?? activePurchase;
    if (purchaseId === null || purchaseId === undefined) throw new Error('Нет активной покупки');
    const res = await createPayment(purchaseId);
    return res;
  };

  if (loading) return <div className="common-page-card">Загружаем практики...</div>;
  if (error && courses.length === 0) return (
    <div className="common-page-card catalog-state">
      <span className="eyebrow">Каталог временно недоступен</span>
      <h1>Программы не загрузились</h1>
      <p>{error}</p>
      <button className="glow-btn" onClick={() => setReloadKey(value => value + 1)}>Попробовать снова</button>
    </div>
  );

  return (
    <div className="common-page-card">
      <span className="eyebrow">Библиотека практик</span>
      <h1 className="common-title">Программы и практики</h1>
      <p className="catalog-intro">{STATIC_DEMO ? 'В демоверсии программы можно бесплатно добавить в личный кабинет и посмотреть занятия. Настоящей оплаты здесь нет.' : 'Посмотрите описание программы и условия участия. Доступные вам занятия находятся в личном кабинете.'}</p>
      <p><Link className="glow-btn" to={localStorage.getItem('alinavit:comparison:token') ? '/courses/pass' : '/auth'}>{localStorage.getItem('alinavit:comparison:token') ? 'Открыть мои занятия' : 'Войти в личный кабинет'}</Link></p>
      {error && <div className="catalog-inline-error" role="status">{error}</div>}
      <div className="common-section">
        {courses && courses.length > 0 ? courses.map(course => (
          <CourseCard
            key={course.id}
            course={course}
            onActivate={() => handleBuy(course.id)}
            actionButton={
              <div className="course-buttons">
                <button 
                  className="course-button buy"
                  onClick={() => handleBuy(course.id)}
                >
                  Добавить
                </button>
              </div>
            }
          />
        )) : <div>Сейчас нет доступных программ</div>}
      </div>

      <PaymentModal
        open={activePurchase !== null}
        onClose={() => setActivePurchase(null)}
        onPay={async (explicitCourseId) => {
          return await doPay(explicitCourseId);
        }}
        course={(Array.isArray(courses) ? courses : []).find(c => c.id === activePurchase)}
      />
    </div>
  );
}

export default BuyCourses;
