import React, { useState, useEffect } from 'react';
import './payment-modal.css';

const PaymentModal = ({ open, onClose, onPay, course, demoMode }) => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  useEffect(() => {
    if (!open) {
      setTimeout(() => {
        setLoading(false);
        setResult(null);
      }, 200);
    }
  }, [open]);

  if (!open) return null;

  const isDemo = demoMode ?? (process.env.REACT_APP_PAYMENT_MOCK === 'true' || process.env.REACT_APP_STATIC_DEMO === 'true');
  const amount = course?.price || course?.course_price?.find(p => p.type === 'RUB')?.price || 0;
  const isFree = isDemo || course?.access_mode === 'free' || amount <= 0;

  const handlePay = async () => {
    setLoading(true);
    setResult(null);
    try {
      const res = await onPay(course?.id);
      setResult({ ok: true, res });
      // If provider returned a confirmation URL, redirect user to provider's page
      const payUrl = res && (
        (res.provider && (
          res.provider.payment_url ||
            (res.provider.confirmation && res.provider.confirmation.confirmation_url) ||
            (res.provider.raw && res.provider.raw.confirmation && res.provider.raw.confirmation.confirmation_url)
        ))
        || res.payment_url
        || (res.confirmation && res.confirmation.confirmation_url)
        || res.confirmation_url
      );
      if (payUrl) {
        try {
          window.location.href = payUrl;
        } catch (err) {
          window.open(payUrl, '_self');
        }
        return;
      }
      if (isFree) {
        setTimeout(() => {
          const base = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
          window.location.href = `${base}/courses/pass`;
        }, 700);
      }
    } catch (e) {
      setResult({ ok: false, error: e.message || String(e) });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="pm-backdrop" role="dialog" aria-modal="true" aria-labelledby="payment-title">
      <div className="pm-modal">
        <button className="pm-close" onClick={onClose} aria-label="Закрыть">✕</button>
        <div className="pm-container">
          <h3 className="pm-title" id="payment-title">{course?.title || `Программа #${course?.id || ''}`}</h3>
          <p className="pm-desc">{course?.description || 'Доступ к программе'}</p>
          
          <div className="pm-summary">
            <div className="pm-summary-row">
              <strong>{isFree ? 'Стоимость доступа:' : 'Сумма к оплате:'}</strong>
              <span className="pm-amount">{isFree ? (isDemo ? 'Бесплатно (тест)' : 'Бесплатно') : `${amount} ₽`}</span>
            </div>
          </div>

          <div className="pm-actions">
            <button 
              className="pm-pay" 
              onClick={handlePay} 
              disabled={loading}
            >
              {loading ? 'Добавляем программу...' : (isFree ? 'Получить бесплатно' : `Оплатить ${amount} ₽`)}
            </button>
            <button 
              className="pm-cancel" 
              onClick={onClose} 
              disabled={loading}
            >
              Отмена
            </button>
          </div>

          {result && !result.ok && (
            <div className="pm-error">
              Ошибка: {result.error}
            </div>
          )}
          {result && result.ok && isFree && (
            <div className="pm-success">Программа добавлена. Открываем «Мой ритм»…</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PaymentModal;
