import React, { useEffect, useMemo, useState } from 'react';
import { Activity, ArrowRight, CalendarDays, CheckCircle2, Circle, Compass, Flag, NotebookPen, Target } from 'lucide-react';
import { Link } from 'react-router-dom';
import { fetchUserbyToken, fetchUserCourses, STATIC_DEMO } from '../../../utils/api';
import CourseCard from '../../../components/Courses/Course-card';
import { checkpointScheduleLabel, compareCheckpointSchedules } from '../../../utils/checkpointSchedule';
import { projectCourseProgress } from '../../../utils/courseProgress';
import './courses-pass.css';

const PassCourses = () => {
  const [courses, setCourses] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const token = localStorage.getItem('alinavit:comparison:token') || '';

  useEffect(() => {
    let mounted = true;
    if (!token) {
      setError('Войдите в аккаунт, чтобы открыть личный кабинет.');
      setLoading(false);
      return () => { mounted = false; };
    }

    Promise.all([fetchUserCourses(token), fetchUserbyToken(token)])
      .then(([courseData, userData]) => {
        if (!mounted) return;
        setCourses(Array.isArray(courseData) ? courseData : []);
        setUser(userData || null);
      })
      .catch(err => { if (mounted) setError(err.message); })
      .finally(() => { if (mounted) setLoading(false); });

    return () => { mounted = false; };
  }, [token]);

  const practiceCourses = useMemo(() => courses.filter(course => course.content_type !== 'checkpoint'), [courses]);
  const checkpoints = useMemo(() => courses.filter(course => course.content_type === 'checkpoint').sort(compareCheckpointSchedules), [courses]);

  const dashboard = useMemo(() => {
    const progress = user?.progress_course || {};
    let lessonCount = 0;
    let viewedCount = 0;

    practiceCourses.forEach(course => {
      const count = (course.sourcesToExercises || course.SourcesToExercises || []).length;
      const entry = projectCourseProgress(course, progress[course.id] || progress[String(course.id)]);
      lessonCount += count;
      viewedCount += Math.min(count, Array.isArray(entry.viewed) ? new Set(entry.viewed).size : 0);
    });

    const percent = lessonCount ? Math.round((viewedCount / lessonCount) * 100) : 0;
    const completedCheckpoints = checkpoints.filter(course => projectCourseProgress(course, progress[course.id]).completed).length;
    return { lessonCount, percent, viewedCount, completedCheckpoints };
  }, [checkpoints, practiceCourses, user]);

  if (loading) return <div className="common-page-card rhythm-state">Собираем ваш ритм...</div>;

  if (error) return (
    <div className="common-page-card rhythm-state">
      <span className="eyebrow">Личный кабинет</span>
      <h1>Мой ритм</h1>
      <p>{error}</p>
      <Link className="cta-primary" to="/auth">Войти или зарегистрироваться <ArrowRight size={16}/></Link>
    </div>
  );

  const progress = user?.progress_course || {};
  const nextCheckpoint = checkpoints.find(course => !projectCourseProgress(course, progress[course.id]).completed);
  const nextCourse = practiceCourses[0] || nextCheckpoint;

  return (
    <section className="rhythm-dashboard">
      <div className="rhythm-dashboard__intro">
        <span className="eyebrow">Личный кабинет участника</span>
        <h1>Мой ритм</h1>
        <p>{user?.username ? `${user.username}, здесь` : 'Здесь'} собраны практики и личная динамика — без соревнования с другими.</p>
      </div>

      <div className="rhythm-dashboard__hero">
        <div className="rhythm-dashboard__stage">
          <span>Текущий ориентир</span>
          <h2>Практики в вашем темпе</h2>
          <p>{practiceCourses.length > 0 || checkpoints.length > 0
            ? 'Продолжайте с небольшого шага и отмечайте только собственные изменения.'
            : 'Начните с одной подходящей программы — остальное можно добавить позже.'}</p>
          {nextCourse ? (
            <Link to={`/courses/pass/${nextCourse.id}`}>Продолжить практику <ArrowRight size={17}/></Link>
          ) : (
            <Link to="/courses/buy">Выбрать первую практику <ArrowRight size={17}/></Link>
          )}
        </div>

        <div className="rhythm-dashboard__progress" aria-label={`Личный прогресс ${dashboard.percent}%`}>
          <div className="rhythm-progress-ring" style={{ '--progress': `${dashboard.percent * 3.6}deg` }}>
            <div><strong>{dashboard.percent}%</strong><span>материалов открыто</span></div>
          </div>
          <dl>
            <div><dt><Activity size={17}/> Практик пройдено</dt><dd>{dashboard.viewedCount} из {dashboard.lessonCount}</dd></div>
            <div><dt><Compass size={17}/> Активных треков</dt><dd>{practiceCourses.length}</dd></div>
            <div><dt><CalendarDays size={17}/> Путь программы</dt><dd>5 месяцев</dd></div>
          </dl>
        </div>
      </div>

      <section className="checkpoint-route" aria-labelledby="checkpoint-route-title">
        <div className="rhythm-dashboard__section-heading">
          <div><span className="eyebrow"><Flag size={15}/> Личный маршрут</span><h2 id="checkpoint-route-title">Контрольные точки</h2></div>
          <span className="checkpoint-route__count">{dashboard.completedCheckpoints} из {checkpoints.length} пройдено</span>
        </div>
        {checkpoints.length > 0 ? (
          <ol className="checkpoint-list">
            {checkpoints.map((checkpoint, index) => {
              const completed = projectCourseProgress(checkpoint, progress[checkpoint.id]).completed;
              return (
                <li className={completed ? 'is-complete' : ''} key={checkpoint.id}>
                  <div className="checkpoint-marker">{completed ? <CheckCircle2/> : <Circle/>}<span>{String(index + 1).padStart(2, '0')}</span></div>
                  <div className="checkpoint-copy"><small>{checkpointScheduleLabel(checkpoint)}</small><h3>{checkpoint.title}</h3><p>{checkpoint.checkpoint_note || checkpoint.description || 'Откройте точку, чтобы увидеть организационные инструкции.'}</p></div>
                  <Link to={`/courses/pass/${checkpoint.id}`}>{completed ? 'Посмотреть' : 'Открыть'} <ArrowRight size={15}/></Link>
                </li>
              );
            })}
          </ol>
        ) : (
          <div className="checkpoint-route__empty"><Flag size={24}/><div><strong>Пять измерений на вашем пути</strong><p>После подтверждения участия здесь появятся входная, три промежуточные и итоговая контрольные точки с инструкциями и сроками.</p></div></div>
        )}
      </section>

      <section className="diary-shortcut" aria-labelledby="diary-shortcut-title">
        <div><span className="eyebrow"><NotebookPen size={15}/> Личное пространство</span>
          <h2 id="diary-shortcut-title">Дневник наблюдений</h2>
          <p>Отметки о вашем состоянии и история небольших шагов — теперь в отдельной вкладке.</p>
        </div>
        <Link className="cta-primary" to="/diary">Открыть дневник <ArrowRight size={16}/></Link>
      </section>
      <div className="rhythm-dashboard__section-heading">
        <div>
          <span className="eyebrow">Библиотека участника</span>
          <h2>Мои практики</h2>
        </div>
        <Link to="/courses/buy"><Target size={17}/> Добавить программу</Link>
      </div>

      {practiceCourses.length > 0 ? (
        <div className="pass-courses-grid">
          {practiceCourses.map(course => (
            <Link key={course.id} className="pass-course-link" to={`/courses/pass/${course.id}`}>
              <CourseCard course={course} actionButton={<span className="pass-course-open">Продолжить →</span>} />
            </Link>
          ))}
        </div>
      ) : (
        <div className="rhythm-dashboard__empty">
          <Compass size={32}/>
          <h3>Здесь появятся выбранные практики</h3>
          <p>В демоверсии их можно добавить бесплатно и сразу проверить прохождение занятий.</p>
          <Link className="cta-primary" to="/courses/buy">Открыть библиотеку <ArrowRight size={16}/></Link>
        </div>
      )}
      <p className="rhythm-dashboard__privacy">Платформа не использует личную отметку как медицинскую оценку. {STATIC_DEMO ? 'В демоверсии она остаётся только в этом браузере.' : 'В рабочей версии она доступна только владельцу аккаунта.'} Исследовательские анкеты появятся лишь после утверждения правил и отдельного согласия.</p>
    </section>
  );
};

export default PassCourses;
