import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './editProfile.css';
import { fetchUserbyToken, updateUserProfile } from '../../../utils/api';

const EditProfile = () => {
    const [userData, setUserData] = useState({
        username: '',
        email: ''
    });
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [emailLocked, setEmailLocked] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const loadUserData = async () => {
            const token = localStorage.getItem('alinavit:comparison:token');
            if (!token) {
                navigate('/auth');
                return;
            }

            try {
                const data = await fetchUserbyToken(token);
                setEmailLocked(!!data.email_change_locked);
                setUserData({
                    username: data.username || '',
                    email: data.email || ''
                });
            } catch (err) {
                    if (process.env.NODE_ENV === 'development') console.error('Ошибка загрузки данных пользователя:', err);
                setError('Не удалось загрузить данные пользователя');
            }
        };

        loadUserData();
    }, [navigate]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setSuccess('');

        try {
            const token = localStorage.getItem('alinavit:comparison:token');
            if (!token) {
                navigate('/auth');
                return;
            }

            await updateUserProfile(token, userData);
            setSuccess('Профиль успешно обновлен');
            
            // Подождем немного, чтобы пользователь увидел сообщение об успехе
            setTimeout(() => {
                navigate('/profile');
            }, 1500);
        } catch (err) {
            if (process.env.NODE_ENV === 'development') console.error('Ошибка обновления профиля:', err);
            setError('Не удалось обновить профиль');
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setUserData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    return (
        <div className="edit-profile-container">
            <form className="edit-profile-form" onSubmit={handleSubmit}>
                <h1>Редактировать профиль</h1>

                <div className="input-group">
                    <label htmlFor="username">Имя пользователя</label>
                    <input
                        type="text"
                        id="username"
                        name="username"
                        value={userData.username}
                        onChange={handleChange}
                        required
                    />
                </div>

                <div className="input-group">
                    <label htmlFor="email">Email</label>
                    <input
                        type="email"
                        disabled={emailLocked}
                        id="email"
                        name="email"
                        value={userData.email}
                        onChange={handleChange}
                        required
                    />
                    {emailLocked && <p>Почта используется для подтверждения входа. Для её смены обратитесь в поддержку.</p>}
                </div>

                {error && <div className="error-message">{error}</div>}
                {success && <div className="success-message">{success}</div>}

                <div className="button-group">
                    <button 
                        type="button" 
                        className="cancel-button"
                        onClick={() => navigate('/profile')}
                    >
                        Отмена
                    </button>
                    <button type="submit" className="save-button">
                        Сохранить
                    </button>
                </div>
            </form>
        </div>
    );
};

export default EditProfile;
