import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { fetchUserbyToken, fetchResearchForms, fetchResearchForm, fetchResearchFormVersions, saveResearchForm, freezeResearchForm, STATIC_DEMO } from '../../utils/api';
import { useSession } from '../../components/Auth/SessionBoundary';
import './researchForms.css';
import ResearchFormAudit from './ResearchFormAudit';

let identifierSequence = 0;
const nextID = (_items, prefix) => `${prefix}_${Date.now().toString(36)}_${++identifierSequence}_${Array.from(crypto.getRandomValues(new Uint32Array(2)), value => value.toString(36)).join('_')}`;
const fieldOfType = (id, type = 'text') => ({ id, type, label: '', help: '', required: false,
  ...(type === 'text' ? { max_length: 1000 } : type === 'number' ? { min: 1, max: 10, step: 1, unit: '', min_label: '', max_label: '' }
    : { options: [{ id: nextID([], 'option'), label: '' }, { id: nextID([], 'option'), label: '' }] }),
});
const emptyDefinition = () => ({ title: '', description: '', kind: 'weekly', fields: [fieldOfType('field_1')] });
const messageFor = error => ({
  400: 'Проверьте поля формы: подписи, границы шкал и варианты ответа.',
  403: 'Доступ администратора отозван. Раздел закрыт.',
  404: 'Серверный раздел форм не включён или форма больше недоступна.',
  409: 'Форма уже изменена. Ваш черновик сохранён на экране. Загрузите актуальную ревизию перед повторным сохранением.',
  503: 'Сервер форм недоступен. На сервер ничего не сохранено.',
}[error.status] || 'Не удалось выполнить действие. Черновик остаётся на экране.');

function Preview({ definition }) {
  return <section className="research-preview" aria-label="Предпросмотр формы">
    <h2>{definition.title || 'Название анкеты'}</h2><p>{definition.description}</p>
    <p className="research-note">Предпросмотр — ответы здесь не вводятся и не отправляются.</p>
    {definition.fields.map((field, index) => <div className="research-preview__question" key={field.id}>
      <strong>{index + 1}. {field.label || 'Вопрос без подписи'}{field.required ? ' · обязательный' : ''}</strong>
      {field.help && <p>{field.help}</p>}
      {field.type === 'text' && <textarea aria-label={`Предпросмотр вопроса ${index + 1}`} disabled rows={2}/>}
      {field.type === 'number' && <p>От {field.min} {field.min_label} до {field.max} {field.max_label}; шаг {field.step}{field.unit ? ` · ${field.unit}` : ''}</p>}
      {field.type === 'single_choice' && <ul>{field.options.map(option => <li key={option.id}>{option.label || 'Вариант без подписи'}</li>)}</ul>}
    </div>)}
  </section>;
}

export default function ResearchForms() {
  const { token } = useSession();
  const [allowed, setAllowed] = useState(false);
  const [loading, setLoading] = useState(true);
  const [connected, setConnected] = useState(false);
  const [drafts, setDrafts] = useState([]);
  const [current, setCurrent] = useState(null);
  const [definition, setDefinition] = useState(emptyDefinition);
  const [savedText, setSavedText] = useState(() => JSON.stringify(emptyDefinition()));
  const [versions, setVersions] = useState([]);
  const [previewRevision, setPreviewRevision] = useState('draft');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [auditRefresh, setAuditRefresh] = useState(0);
  const loseAccess = useCallback(status => { setAllowed(false); setMessage(status === 401 ? 'Сессия истекла. Войдите снова.' : 'Доступ администратора отозван. Раздел закрыт.'); }, []);
  const pending = useRef(false);
  const dirty = JSON.stringify(definition) !== savedText;

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const user = await fetchUserbyToken(token);
        if (!alive) return;
        if (!user?.is_admin) { setMessage('Нужен аккаунт администратора.'); return; }
        setAllowed(true);
        if (STATIC_DEMO) return;
        const list = await fetchResearchForms(token);
        if (alive) { setDrafts(list); setConnected(true); }
      } catch (error) {
        if (alive) { setMessage(messageFor(error)); if (error.status === 403) setAllowed(false); }
      } finally { if (alive) setLoading(false); }
    })();
    return () => { alive = false; };
  }, [token]);

  useEffect(() => {
    if (!dirty) return undefined;
    const warn = event => { event.preventDefault(); event.returnValue = ''; };
    window.addEventListener('beforeunload', warn);
    return () => window.removeEventListener('beforeunload', warn);
  }, [dirty]);

  const acceptDraft = draft => {
    setCurrent(draft); setDefinition(draft.definition); setSavedText(JSON.stringify(draft.definition)); setPreviewRevision('draft');
    setDrafts(previous => [draft, ...previous.filter(item => item.id !== draft.id)]);
    setAuditRefresh(value => value + 1);
  };
  const run = async action => {
    if (pending.current) return;
    pending.current = true; setBusy(true); setMessage('');
    try { await action(); } catch (error) { setMessage(messageFor(error)); if (error.status === 403) setAllowed(false); }
    finally { pending.current = false; setBusy(false); }
  };
  const selectDraft = id => {
    if (pending.current) return;
    if (dirty && !window.confirm('Несохранённые изменения будут потеряны. Продолжить?')) return;
    if (!id) { const empty = emptyDefinition(); setCurrent(null); setDefinition(empty); setSavedText(JSON.stringify(empty)); setVersions([]); setPreviewRevision('draft'); setMessage(''); return; }
    run(async () => {
      const [draft, history] = await Promise.all([fetchResearchForm(token, id), fetchResearchFormVersions(token, id)]);
      acceptDraft(draft); setVersions(history);
    });
  };
  const updateField = (index, changes) => setDefinition(previous => ({ ...previous, fields: previous.fields.map((field, n) => n === index ? { ...field, ...changes } : field) }));
  const changeType = (index, type) => setDefinition(previous => ({ ...previous, fields: previous.fields.map((field, n) => n === index ? { ...fieldOfType(field.id, type), label: field.label, help: field.help, required: field.required } : field) }));
  const moveField = (index, direction) => setDefinition(previous => {
    const fields = [...previous.fields]; [fields[index], fields[index + direction]] = [fields[index + direction], fields[index]];
    return { ...previous, fields };
  });
  const save = event => {
    event.preventDefault();
    if (!connected) return;
    run(async () => { const draft = await saveResearchForm(token, definition, current?.id, current?.revision); acceptDraft(draft); setMessage(`Черновик сохранён на сервере. Ревизия ${draft.revision}.`); });
  };
  const freeze = () => {
    if (!connected || !current || dirty) return;
    run(async () => {
      const version = await freezeResearchForm(token, current.id, current.revision);
      setVersions(previous => [version, ...previous.filter(item => item.revision !== version.revision)].sort((a, b) => b.revision - a.revision));
      setPreviewRevision(String(version.revision)); setMessage(`Версия ${version.revision} зафиксирована для проверки. Участникам она не опубликована.`);
      setAuditRefresh(value => value + 1);
    });
  };
  const download = () => {
    const url = URL.createObjectURL(new Blob([JSON.stringify({ definition, status: 'unapproved_draft' }, null, 2)], { type: 'application/json' }));
    const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'rhythm-form-draft.json'; anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    setMessage('Скачан черновик вопросов, без ответов участников. Это не сохранение на сервере.');
  };

  if (loading) return <div className="admin-state">Открываем конструктор форм…</div>;
  if (!allowed) return <div className="admin-state">{message || 'Доступ запрещён. Нужен аккаунт администратора.'}</div>;
  const preview = previewRevision === 'draft' ? definition : versions.find(version => String(version.revision) === previewRevision)?.definition || definition;
  return <section className="research-editor">
    <header><span className="eyebrow">Кабинет автора</span><h1>Анкеты проекта</h1><p>Составьте вопросы, проверьте предпросмотр и зафиксируйте версию. Этот раздел не собирает ответы участников.</p><Link to="/profile">Вернуться в кабинет</Link></header>
    {!connected && <p className="research-note" role="note">{STATIC_DEMO ? 'Режим макета: сервер не подключён к демоверсии.' : 'Нет подключения к серверному разделу форм.'} Можно подготовить вопросы и скачать черновик. Сохранение и фиксация на сервере недоступны.</p>}
    {message && <p className="research-message" role="status">{message}</p>}
    <div className="research-toolbar">
      <label>Открыть черновик<select disabled={busy || !connected} value={current?.id || ''} onChange={event => selectDraft(event.target.value)}><option value="">Новая форма</option>{drafts.map(draft => <option key={draft.id} value={draft.id}>{draft.definition.title} · ревизия {draft.revision}</option>)}</select></label>
      {!STATIC_DEMO && <button type="button" disabled={busy} onClick={() => run(async () => { const list = await fetchResearchForms(token); setDrafts(list); setConnected(true); setMessage('Подключение к серверу проверено. Черновик на экране не изменён.'); })}>Проверить подключение</button>}
      {current && <button type="button" disabled={busy} onClick={() => selectDraft(current.id)}>Загрузить актуальную ревизию</button>}
      <span>{current ? `Ревизия ${current.revision}` : 'Новый черновик'}{dirty ? ' · есть несохранённые изменения' : ''}</span>
    </div>
    <ResearchFormAudit key={`${token}:${current?.id || 'new'}`} token={token} formId={current?.id} connected={connected && !STATIC_DEMO} refreshKey={auditRefresh} onAccessLost={loseAccess}/>
    <div className="research-layout">
      <form onSubmit={save} aria-label="Редактор формы"><fieldset disabled={busy}>
        <legend>Вопросы и настройки</legend>
        <label>Название формы<input required maxLength={160} value={definition.title} onChange={event => setDefinition({ ...definition, title: event.target.value })}/></label>
        <label>Вид формы<select value={definition.kind} onChange={event => setDefinition({ ...definition, kind: event.target.value })}><option value="weekly">Недельная обратная связь</option><option value="daily">Дневник наблюдений</option><option value="checkpoint">Контрольное измерение</option></select></label>
        <label>Инструкция к форме<textarea maxLength={4000} value={definition.description} onChange={event => setDefinition({ ...definition, description: event.target.value })}/></label>
        {definition.fields.map((field, index) => <fieldset className="research-field" key={field.id}>
          <legend>Вопрос {index + 1}</legend><small>Постоянный код: {field.id}</small>
          <label>Текст вопроса {index + 1}<input required maxLength={500} value={field.label} onChange={event => updateField(index, { label: event.target.value })}/></label>
          <label>Пояснение {index + 1}<textarea maxLength={2000} value={field.help || ''} onChange={event => updateField(index, { help: event.target.value })}/></label>
          <label>Тип ответа {index + 1}<select value={field.type} onChange={event => changeType(index, event.target.value)}><option value="text">Текст</option><option value="number">Число или шкала</option><option value="single_choice">Один вариант</option></select></label>
          <label className="research-checkbox"><input type="checkbox" checked={field.required} onChange={event => updateField(index, { required: event.target.checked })}/>Обязательный вопрос {index + 1}</label>
          {field.type === 'text' && <label>Максимум символов {index + 1}<input required type="number" min="1" max="4000" value={field.max_length} onChange={event => updateField(index, { max_length: event.target.value === '' ? '' : Number(event.target.value) })}/></label>}
          {field.type === 'number' && <div className="research-numeric">
            {[['min', 'Минимум'], ['max', 'Максимум'], ['step', 'Шаг']].map(([key, label]) => <label key={key}>{label} {index + 1}<input required type="number" step="any" value={field[key]} onChange={event => updateField(index, { [key]: event.target.value === '' ? '' : Number(event.target.value) })}/></label>)}
            {[['unit', 'Единицы'], ['min_label', 'Подпись минимума'], ['max_label', 'Подпись максимума']].map(([key, label]) => <label key={key}>{label} {index + 1}<input maxLength={key === 'unit' ? 40 : 160} value={field[key] || ''} onChange={event => updateField(index, { [key]: event.target.value })}/></label>)}
          </div>}
          {field.type === 'single_choice' && <div>{field.options.map((option, optionIndex) => <div className="research-option" key={option.id}>
            <label>Вариант {optionIndex + 1} вопроса {index + 1}<input required maxLength={200} value={option.label} onChange={event => updateField(index, { options: field.options.map(item => item.id === option.id ? { ...item, label: event.target.value } : item) })}/></label>
            <button type="button" disabled={field.options.length <= 2} aria-label={`Убрать вариант ${optionIndex + 1} вопроса ${index + 1}`} onClick={() => updateField(index, { options: field.options.filter(item => item.id !== option.id) })}>Убрать</button>
          </div>)}<button type="button" disabled={field.options.length >= 30} onClick={() => updateField(index, { options: [...field.options, { id: nextID(field.options, 'option'), label: '' }] })}>Добавить вариант к вопросу {index + 1}</button></div>}
          <div className="research-field__actions"><button type="button" disabled={index === 0} onClick={() => moveField(index, -1)} aria-label={`Поднять вопрос ${index + 1}`}>Выше</button><button type="button" disabled={index === definition.fields.length - 1} onClick={() => moveField(index, 1)} aria-label={`Опустить вопрос ${index + 1}`}>Ниже</button><button type="button" disabled={definition.fields.length === 1} onClick={() => setDefinition({ ...definition, fields: definition.fields.filter(item => item.id !== field.id) })}>Убрать вопрос {index + 1}</button></div>
        </fieldset>)}
        <button type="button" disabled={definition.fields.length >= 100} onClick={() => setDefinition({ ...definition, fields: [...definition.fields, fieldOfType(nextID(definition.fields, 'field'))] })}>Добавить вопрос</button>
        <div className="research-actions"><button type="submit" disabled={!connected}>Сохранить черновик</button><button type="button" disabled={!connected || !current || dirty} onClick={freeze}>Зафиксировать версию</button><button type="button" onClick={download}>Скачать черновик JSON</button></div>
        <p className="research-note">Перед фиксацией сохраните изменения. Фиксация создаёт неизменяемую копию для проверки, но не публикует форму участникам.</p>
        <p className="research-note">Несохранённый черновик существует только на этой странице. Перед уходом сохраните его на сервере или скачайте копию.</p>
      </fieldset></form>
      <aside><label>Предпросмотр<select value={previewRevision} onChange={event => setPreviewRevision(event.target.value)}><option value="draft">Текущий черновик</option>{versions.map(version => <option key={version.revision} value={version.revision}>Зафиксированная версия {version.revision}</option>)}</select></label><Preview definition={preview}/></aside>
    </div>
  </section>;
}
