// Небольшая обёртка для создания платежа
import { buildUrl, STATIC_DEMO } from './api';
import { demoPurchase } from './demoApi';
import { sessionFetch } from './sessionFetch';

export async function createPayment(courseId) {
  try {
    const token = localStorage.getItem('alinavit:comparison:token');
    if (!token) throw new Error('Необходимо авторизоваться');
    if (STATIC_DEMO) return demoPurchase(token, courseId);

    const res = await sessionFetch(buildUrl('/payments/create'), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
      },
      body: JSON.stringify({ course_id: courseId }),
    });
    if (!res.ok) throw new Error(`Ошибка платежа: ${res.status}`);
    const data = await res.json();
    if (process.env.NODE_ENV === 'development') {
      // eslint-disable-next-line no-console
      console.debug('createPayment response', data);
    }
    return data;
  } catch (err) {
    // Фоллбек: мок-ответ для локальной разработки
    if (process.env.NODE_ENV === 'development') {
      // eslint-disable-next-line no-console
      console.warn('Payment backend unavailable', err.message);
    }
    // Фоллбек: не возвращаем реальную ссылку провайдера — сообщаем об ошибке
    if (err.status === 401) throw err;
    throw new Error('Не удалось оформить доступ. Попробуйте ещё раз позже.');
  }
}

const payment = { createPayment };
export default payment;
