import React, { useEffect, useRef, useState } from 'react';
import { ArrowRight, CheckCircle2, Clock3, Send, ShieldCheck } from 'lucide-react';
import { Link } from 'react-router-dom';
import { fetchParticipationApplication, fetchUserbyToken, saveParticipationApplication } from '../../utils/api';
import './participation.css';

const statusLabels = {
  pending: 'Заявка получена',
  contacted: 'Алина свяжется с вами',
  accepted: 'Участие подтверждено',
  declined: 'Сейчас формат не подходит',
};

const Participation = () => {
  const token = localStorage.getItem('alinavit:comparison:token') || '';
  const [user, setUser] = useState(null);
  const [application, setApplication] = useState(null);
  const [availability, setAvailability] = useState('ready');
  const [message, setMessage] = useState('');
  const [adultConfirmed, setAdultConfirmed] = useState(false);
  const [privacyAcknowledged, setPrivacyAcknowledged] = useState(false);
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState('');
  const [saving, setSaving] = useState(false);
  const pending = useRef(false);

  useEffect(() => {
    let mounted = true;
    Promise.all([fetchUserbyToken(token), fetchParticipationApplication(token)])
      .then(([userData, saved]) => {
        if (!mounted) return;
        setUser(userData);
        setApplication(saved);
        if (saved) {
          setAvailability(saved.availability || 'ready');
          setMessage(saved.message || '');
          setAdultConfirmed(!!saved.adult_confirmed);
          setPrivacyAcknowledged(!!saved.privacy_acknowledged);
        }
      })
      .catch(error => { if (mounted) setStatus(error.message || 'Не удалось загрузить заявку.'); })
      .finally(() => { if (mounted) setLoading(false); });
    return () => { mounted = false; };
  }, [token]);

  const handleSubmit = async event => {
    event.preventDefault();
    if (pending.current) return;
    if (!adultConfirmed || !privacyAcknowledged) {
      setStatus('Подтвердите возраст и ознакомление с правилами обработки данных.');
      return;
    }
    pending.current = true;
    setSaving(true);
    setStatus('Отправляем заявку…');
    try {
      const saved = await saveParticipationApplication(token, {
        availability,
        message,
        adult_confirmed: adultConfirmed,
        privacy_acknowledged: privacyAcknowledged,
      });
      setApplication(saved);
      setStatus('Заявка сохранена. Её статус появился в вашем кабинете.');
    } catch (error) {
      setStatus(error.message || 'Не удалось сохранить заявку.');
    } finally {
      pending.current = false;
      setSaving(false);
    }
  };

  if (loading) return <div className="common-page-card participation-state">Готовим форму участия…</div>;

  return (
    <section className="participation-page">
      <header className="participation-hero">
        <span className="eyebrow">Предварительная заявка</span>
        <h1>Начать путь<br/>в своём ритме</h1>
        <p>{user?.username ? `${user.username}, ` : ''}здесь нет медицинской анкеты и автоматического отбора. Заявка помогает Алине понять вашу готовность и связаться после утверждения условий набора.</p>
      </header>

      {application && (
        <div className={`participation-status is-${application.status || 'pending'}`}>
          {application.status === 'accepted' ? <CheckCircle2/> : <Clock3/>}
          <div><span>Текущий статус</span><strong>{statusLabels[application.status] || statusLabels.pending}</strong><p>Обновлено: {new Date(typeof application.updated_at === 'number' ? application.updated_at * 1000 : application.updated_at).toLocaleDateString('ru-RU')}</p></div>
        </div>
      )}

      <form className="participation-form" onSubmit={handleSubmit}>
        <div className="participation-form__heading"><div><span className="eyebrow">Шаг 1 из 1</span><h2>Расскажите о готовности</h2></div><ShieldCheck size={28}/></div>

        <fieldset>
          <legend>Как вы сейчас относитесь к пятимесячному формату?</legend>
          <label className={availability === 'ready' ? 'is-selected' : ''}><input type="radio" name="availability" value="ready" checked={availability === 'ready'} onChange={event => setAvailability(event.target.value)}/><span><strong>Готов(а) участвовать регулярно</strong><small>Понимаю, что важна последовательность, а не идеальное выполнение.</small></span></label>
          <label className={availability === 'need_details' ? 'is-selected' : ''}><input type="radio" name="availability" value="need_details" checked={availability === 'need_details'} onChange={event => setAvailability(event.target.value)}/><span><strong>Сначала хочу уточнить детали</strong><small>Нужна информация о нагрузке, датах или формате обратной связи.</small></span></label>
        </fieldset>

        <label className="participation-message" htmlFor="participation-message">Что для вас важно уточнить? <small>Не указывайте диагнозы и другие сведения о здоровье.</small></label>
        <textarea id="participation-message" value={message} maxLength={600} onChange={event => setMessage(event.target.value)} rows={5} placeholder="Можно оставить поле пустым или написать вопрос о формате…"/>
        <div className="participation-counter">{message.length}/600</div>

        <div className="participation-confirmations">
          <label><input type="checkbox" checked={adultConfirmed} onChange={event => setAdultConfirmed(event.target.checked)}/><span>Мне исполнилось 18 лет.</span></label>
          <label><input type="checkbox" checked={privacyAcknowledged} onChange={event => setPrivacyAcknowledged(event.target.checked)}/><span>Я ознакомился(-ась) с тестовыми <Link to="/privacy">правилами обработки данных</Link> и <Link to="/terms">условиями участия</Link>.</span></label>
        </div>

        {application && <p>Можно уточнить вопрос или удобный формат участия. Уже установленный статус заявки при обновлении сохранится.</p>}
        <div className="participation-actions"><button type="submit" disabled={saving}><Send size={17}/> {saving ? 'Сохраняем…' : application ? 'Обновить заявку' : 'Отправить заявку'}</button><Link to="/support">Вернуться к условиям <ArrowRight size={15}/></Link></div>
        {status && <p className="participation-form__status" role="status">{status}</p>}
      </form>

      <p className="participation-disclaimer">Отправка этой формы не является медицинским согласием и не гарантирует включение в программу. Полные условия и отдельные согласия будут предоставлены до начала участия.</p>
    </section>
  );
};

export default Participation;
