import './App.css';
import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import { Home } from './pages/Home/Home';
import Courses from './pages/Courses/Courses';
import BuyCourses from './pages/Courses/buy/Courses-buy';
import PassCourses from './pages/Courses/pass/Courses-pass';
import CourseDetail from './pages/Courses/pass/CourseDetail';

import Profile from './pages/Profile/Profile';
import Support from './pages/Support/Support';
import Participation from './pages/Participation/Participation';
import Notifications from './pages/Notifications/Notifications';
import About from './pages/About/About';
import Diary from './pages/Diary/Diary';
import Checkauth from './handlers/CheckAuth/Checkauth';
import { Layout } from './components/layout/Layout';
import Auth from './components/Auth/Auth';
import SessionBoundary from './components/Auth/SessionBoundary';
import Reg from './components/Reg/Reg';
import YooKassaIP from './pages/YooKassaIP/YooKassaIP';
import EditProfile from './components/profile/edit/EditProfile';
import Terms from './pages/Legal/Terms';
import Privacy from './pages/Legal/Privacy';
import CourseEditor from './pages/Admin/CourseEditor';
import UserManagement from './pages/Admin/UserManagement';
import ApplicationManagement from './pages/Admin/ApplicationManagement';
import ResearchForms from './pages/Admin/ResearchForms';


function App() {

    const configuredBase = process.env.PUBLIC_URL || '';
    const routerBase = configuredBase.startsWith('http')
        ? new URL(configuredBase).pathname
        : configuredBase;

    return (
        <div className='App'>
            <BrowserRouter basename={routerBase || undefined}>
                <SessionBoundary>
                <Layout>
                    <Routes>
                        <Route path='/' element={
                            <Home />} />
                        <Route path='/courses' element={
                            <Checkauth>
                                <Courses />
                            </Checkauth>} />
                        <Route path='/profile' element={
                            <Checkauth>
                                <Profile />
                            </Checkauth>} />
                        <Route path='/courses/buy' element={
                            <BuyCourses />} />
                        <Route path='/courses/pass' element={
                            <Checkauth>
                                <PassCourses />
                            </Checkauth>} />
                        <Route path='/courses/pass/:id' element={
                            <Checkauth>
                                <CourseDetail />
                            </Checkauth>} />
                        <Route path='/support' element={
                            <Support />} />
                        <Route path='/participation' element={
                            <Checkauth>
                                <Participation />
                            </Checkauth>} />
                        <Route path='/notifications' element={
                            <Checkauth>
                                <Notifications />
                            </Checkauth>} />
                        <Route path='/about' element={
                            <About />} />
                        <Route path='/auth' element={<Auth/>} />
                        <Route path='/diary' element={<Checkauth><Diary /></Checkauth>} />
                            <Route path='/reg' element={<Reg/>} />
                        <Route path='/profile/edit' element={
                            <Checkauth>
                                <EditProfile />
                            </Checkauth>
                        } />
                        <Route path='/yookassa-ip' element={
                            <YooKassaIP />
                        } />
                        <Route path='/admin/courses-editor' element={
                            <Checkauth>
                                <CourseEditor />
                            </Checkauth>
                        } />
                        <Route path='/admin/users' element={
                            <Checkauth>
                                <UserManagement />
                            </Checkauth>
                        } />
                        <Route path='/admin/applications' element={
                            <Checkauth>
                                <ApplicationManagement />
                            </Checkauth>
                        } />
                        <Route path='/admin/research-forms' element={<Checkauth><ResearchForms /></Checkauth>} />
                        <Route path='/terms' element={<Terms/>} />
                        <Route path='/privacy' element={<Privacy/>} />
                        <Route path='*' element={<Navigate to="/about" replace />} />
                    </Routes>
                </Layout>
                </SessionBoundary>
            </BrowserRouter>
        </div>
    );
}

export default App;
